insert into pal_eyes.sites (id,slug,name_ar,name_en,governorate_ar,locality_ar,site_type_ar,page_category,workflow_status,publication_status,coordinate_status,original_draft_profile,editorial_draft,source_count,held_claim_count,version_number,metadata) values ('site-ee0e5bf1f753','rfh-ltrykhy-ee0e5b','رفح التاريخية','Historic Rafah','رفح','رفح','عنقود عمراني تاريخي مؤقت','GOVERNED_DRAFT_PAGE','GOVERNED_DRAFT','BLOCKED','MISSING','expandedNarrative','بحسب قائمة اليونسكو المحدثة في 25 مارس 2026، تحققت المنظمة حتى 24 مارس 2026 من وقوع ضرر في تل رفح؛ ولا يمتد هذا الإثبات تلقائياً إلى كامل النسيج الحضري التاريخي لرفح.',1,3,1,'{"candidate_identity_status":"reclassified_to_governed_cluster","special_hold":null,"draft_label_required":true,"original_source_sha256":"1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d","original_source_line_count":5334}'::jsonb) on conflict (id) do update set slug=excluded.slug,name_ar=excluded.name_ar,name_en=excluded.name_en,governorate_ar=excluded.governorate_ar,locality_ar=excluded.locality_ar,site_type_ar=excluded.site_type_ar,page_category=excluded.page_category,workflow_status=excluded.workflow_status,publication_status=excluded.publication_status,coordinate_status=excluded.coordinate_status,original_draft_profile=excluded.original_draft_profile,editorial_draft=excluded.editorial_draft,source_count=excluded.source_count,held_claim_count=excluded.held_claim_count,metadata=excluded.metadata;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-4aeec5656d1d','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','أقدس موقع إسلامي بعد مكة والمدينة، بناه الخليفة عمر بن الخطاب ووسعه الأمويون. يتضمن قبة الصخرة والمسجد القبلي والمصليات المروانية.','[{"title":"الموقع والجغرافيا المقدسة","draft_text":"يقع المسجد الأقصى المبارك على هضبة الحرم القدسي الشريف في الزاوية الجنوبية الشرقية من البلدة القديمة للقدس، على مساحة تبلغ نحو 144 دونماً. هذه الهضبة ليست مجرد قطعة أرض مرتفعة، بل هي قلب فلسطين الجيولوجي والروحي. اختيار هذا الموقع للعبادة لم يكن اعتباطياً؛ فالتضاريس الطبيعية جعلت منه نقطة دفاعية مطلة على وادي قدرون شرقاً ووادي جهنم جنوباً، مما أعطاه قدسية استراتيجية قبل أن يكون دينية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"ما قبل الإسلام: قدسية متجذرة","draft_text":"الرواية الفلسطينية لا تبدأ من الفتح الإسلامي فقط، بل تمتد إلى جذور المكان. يُعتقد أن الموقع كان معبداً كنعانياً قديماً، وهو أمر منطقي لمدينة قدسية اسمها \"أور سالم\" (مدينة السلام) أسسها اليبوسيون الكنعانيون. ثم شيد النبي سليمان هيكله هنا (القرن العاشر ق.م)، وأعاد بناؤه اليهود بعد السبي، ثم وسّعه هيرودس الأدومي (القرن الأول ق.م) بشكل هائل. دمر الرومان الهيكل عام 70م، وأقاموا معبداً لجوبيتر فوق أنقاضه. هذه الطبقات المتعاقبة تؤكد أن قدسية المكان سابقة لكل الأديان، وأن كل قادم جديد بنى على ما سبقه، دون أن يلغي حق من سبقه. وهنا ترفض الرواية الفلسطينية الرواية الإسرائيلية التي تزعم وجود الهيكل تحت الأقصى وتطالب بهدمه؛ فالآثار الموجودة تحت الحرم هي آثار رومانية وبيزنطية وإسلامية، والهيكل -إن وُجد- فهو طبقة أثرية من طبقات عديدة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الفتح الإسلامي: عهد عمر بن الخطاب","draft_text":"في عام 15هـ/636م، تسلم الخليفة عمر بن الخطاب مفاتيح القدس صلحاً من بطريركها صفرونيوس، بعد حصار لم يسفك فيه دماء. العهدة العمرية هي الوثيقة التأسيسية للوجود الإسلامي في القدس؛ تضمن للمسيحيين كنائسهم وأمنهم مقابل الجزية. تروي الرواية الفلسطينية أن عمر رفض الصلاة في كنيسة القيامة حين أدركه وقت الصلاة، خشية أن يتخذها المسلمون مسجداً من بعده. هذا الفعل النبيل هو الذي جعل الأقصى يُبنى في موقعه الحالي؛ فأراد عمر أن يكون للمسلمين مسجدهم المستقل. توجه إلى الهضبة المهملة التي كانت مكباً للنفايات الرومانية، ونظفها بنفسه، وبنى في طرفها الجنوبي مسجداً خشبياً يتسع لثلاثة آلاف مصلٍّ. هنا تبدأ الرواية الإسلامية الفلسطينية للمكان: ربطه بالمعراج النبوي، وتطهيره من الإهمال الروماني.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الأموي: البناء التأسيسي","draft_text":"الخليفة عبد الملك بن مروان وابنه الوليد هم من أعطوا الحرم شكله المعماري الخالد. بنى عبد الملك قبة الصخرة (72هـ/691م) فوق الصخرة التي يُعتقد أن النبي محمداً عرج منها إلى السماء. القبة ليست مسجداً للصلاة بل مشهداً تذكارياً، بُني ليكون تحفة معمارية تنافس الكنائس البيزنطية. قطر قبتها 20 متراً وارتفاعها 35 متراً، وزُينت بالفسيفساء والرخام والآيات القرآنية. أما ابنه الوليد فبنى المسجد القبلي (المصلى الرئيسي) في جنوب الحرم، وجعله مسجداً جامعاً. وثيقة تاريخية نادرة عُثر عليها في خرائب المسجد القبلي تعود للعصر الأموي تذكر اسم بانيه وأرخ بنائه. (مصدر: كتاب \"تاريخ المسجد الأقصى\" – د. عبد الله معروف).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العباسيون والفاطميون: الإهمال والزلازل","draft_text":"مرت على الأقصى فترات عصيبة. الزلازل المتتالية (خاصة زلزال 746م و1033م) دمرت أجزاء كبيرة من المسجد القبلي. الخلفاء الفاطميون، وخاصة الظاهر لإعزاز دين الله، أعادوا بناء المسجد القبلي بشكله الحالي تقريباً سنة 1035م، وقلصوا عرضه وطولوا رواقه الأوسط ليكون صحناً مكشوفاً. هذه الفترة شهدت أيضاً الاستيطان الصليبي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الأيوبيون والمماليك: استرداد وتجديد","draft_text":"حين حرر صلاح الدين الأيوبي القدس عام 1187م، كان الصليبيون قد حولوا المسجد الأقصى إلى قصر وإسطبلات، وقبة الصخرة إلى كنيسة (Templum Domini). أول ما فعله صلاح الدين هو تطهير الحرم بالماء والطيب، وإزالة الصلبان، وإعادة المحراب إلى اتجاهه الصحيح نحو مكة، ونصب المنبر الخشبي الرائع الذي حمله خصيصاً من حلب (منبر نور الدين زنكي). هذا المنبر، الذي احترقه متطرف يهودي عام 1969، كان تحفة فنية من آلاف القطع الخشبية المتشابكة دون مسمار واحد، ويمثل ذروة الفن الخشبي الإسلامي.\n\nالمماليك هم أكثر من ترك بصماته المعمارية على الحرم. أضافوا الأروقة الحجرية المحيطة بقبة الصخرة، والمآذن، والمدارس (كالمدرسة الأشرفية قبالة المسجد القبلي)، والأسبلة، وقباباً متعددة (قبة النحوية، قبة موسى، قبة الأرواح). (مصدر: \"تاريخ القدس\" – مجير الدين الحنبلي، تحقيق د. عبد الله عطيات).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر العثماني: الإدارة والترميم","draft_text":"أولى السلاطين العثمانيون، بدءاً من سليم الأول ثم سليمان القانوني، الحرم اهتماماً كبيراً. سليمان القانوني هو من جدد الفسيفساء الخارجية لقبة الصخرة، وأضاف الكاشان (البلاطات الخزفية) الفارسي، وبنى سور القدس الحالي. أنشأ نظاماً وقفياً دقيقاً لإدارة الحرم من خلال دار الأيتام (التكية) وعدة أوقاف عقارية. سجلات المحكمة الشرعية في القدس تحوي آلاف الوثائق عن تعيينات \"خدام الحرم\" و\"البوابين\" و\"المؤذنين\"، وعن رواتبهم ومخصصاتهم، مما يدل على مؤسسة دينية واجتماعية ضخمة. (مصدر: سجلات محكمة القدس الشرعية، أرشيف دار الوثائق).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الحديث: الاحتلال والمقاومة الشعبية","draft_text":"لا تكتمل الرواية الفلسطينية دون ذكر النكبة عام 1948 وما تلاها. احتلت إسرائيل القدس الشرقية عام 1967، وفرضت سيطرتها على الحرم القدسي. محاولة إحراق المسجد القبلي عام 1969 على يد متطرف أسترالي يهودي كانت صدمة للمسلمين جميعاً. ومنذ ذلك الحين، والمسجد الأقصى يتعرض لاقتحامات المستوطنين المتكررة بحماية الجيش الإسرائيلي، ومحاولات تقسيمه زمانياً ومكانياً.\n\nالرواية الفلسطينية هنا تنتقل من التاريخ إلى الحاضر الحي. المرابطون والمرابطات في الأقصى، وهم رجال ونساء فلسطينيون من القدس والداخل المحتل، يتولون حراسة المسجد والرباط فيه ليل نهار لمنع المستوطنين من تدنيسه. هم امتداد لخدام الحرم عبر القرون. انتفاضة البوابات الإلكترونية عام 2017، حين انتفض المقدسيون رفضاً لتركيب بوابات إلكترونية على مداخل الأقصى، وأقاموا الصلاة في الشوارع أياماً حتى أزيلت، هي ملحمة بطولية معاصرة تؤكد أن الأقصى لا يُدار بقرارات خارجية، بل بإرادة الشعب الفلسطيني. (مصادر: أرشيف وكالة وفا، مركز القدس للحقوق الاجتماعية والاقتصادية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"المسجد الأقصى المبارك ليس مجرد بناء حجري، بل هو هوية فلسطينية متجسدة. من تطهير عمر بن الخطاب للمكان، إلى بناء الأمويين لقبة الصخرة، إلى تجديد المماليك لأروقته، إلى رباط المرابطين اليوم، المكان هو شاهد على ارتباط الشعب الفلسطيني بأرضه ودفاعه عن مقدساته عبر أربعة عشر قرناً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تاريخ القدس\" – مجير الدين الحنبلي، \"الموسوعة الفلسطينية\"، موقع دائرة الأوقاف الإسلامية"]'::jsonb,'["أموي","عباسي","فاطمي","أيوبي","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f9df0c7e708c','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','موقع "عين سلوان" الكنعانية، بها قنوات مائية قديمة.','[]'::jsonb,'["\"آثار فلسطين\" – كاثلين كينيون، \"دائرة الآثار الفلسطينية\""]'::jsonb,'["كنعاني","روماني","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f9067873c322','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','جزء من السور الغربي للحرم القدسي، ربطه الفلسطينيون بالبراق النبوي. منذ العهد الإسلامي هو وقف إسلامي.','[{"title":"ما هو حائط البراق؟","draft_text":"حائط البراق هو جزء مكشوف من السور الغربي الضخم للحرم القدسي الشريف، يبلغ طوله حوالي 48 متراً وارتفاعه 18 متراً. بُني هذا السور كجزء من مشروع توسعة هيرودس الكبير للحرم في القرن الأول ق.م، لكنه ليس بناءً يهودياً خالصاً كما تروج الرواية الإسرائيلية؛ فالمهندسون الذين بنوه كانوا فينيقيين وروماناً، والحجارة قطعت بأيدٍ كنعانية محلية. الجدار هو مجرد جدار استنادي ضخم الغرض منه رفع مستوى أرض الحرم لتكون منبسطة، وليس له أي قدسية دينية يهودية في أصله.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التسمية: البراق، وليس المبكى","draft_text":"الرواية الفلسطينية تصحح التسمية: الاسم الصحيح هو \"حائط البراق\"، نسبة إلى دابة البراق التي ربطها النبي محمد صلى الله عليه وسلم عند هذا الجدار ليلة الإسراء والمعراج، حسب الرواية الإسلامية. هذه التسمية متأصلة في الوقف الإسلامي منذ قرون. أما تسمية \"حائط المبكى\" (Wailing Wall) فهي تسمية غربية استشراقية ظهرت في القرن 19، تصف بكاء اليهود عند الجدار، وقد تبناها الصهاينة لجعله رمزاً قومياً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"تاريخ الوقفية الإسلامية","draft_text":"منذ الفتح الإسلامي، كان حائط البراق جزءاً لا يتجزأ من الوقف الإسلامي للحرم القدسي. لم يكن لليهود أي حقوق ملكية أو سيطرة عليه. في العصر العثماني، سُمح لليهود بالصلاة عنده لفترات قصيرة، كتسامح ديني، لكن دون أي اعتراف بحقهم فيه. كان المقدسيون يمرون من أمامه يومياً في طريقهم إلى المسجد الأقصى عبر حارة المغاربة الملاصقة له. في العشرينيات والثلاثينيات من القرن الماضي، حاول الصهاينة تغيير الوضع القائم عنده بإحضار كراسٍ وستائر لفصل المصلين، مما أثار احتجاجات الفلسطينيين وصولاً إلى ثورة البراق عام 1929.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النكبة والتهويد","draft_text":"بعد نكبة 1948، سيطر الأردن على القدس الشرقية وبقي الجدار تحت السيادة الإسلامية. لكن بعد احتلال 1967، هدمت إسرائيل حارة المغاربة الفلسطينية بالكامل (138 منزلاً) خلال 48 ساعة فقط، وشردت سكانها، لإنشاء \"ساحة المبكى\" الحالية. هذا التدمير لم يكن مجرد تطهير عرقي، بل كان محواً للرواية الفلسطينية؛ فاختفاء الحارة يعني اختفاء الشاهد على أن الجدار كان جزءاً من نسيج سكني فلسطيني إسلامي، وليس موقعاً منعزلاً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الرواية الفلسطينية: نضال متواصل","draft_text":"اليوم، الرواية الفلسطينية عن حائط البراق لا تنفصل عن النضال من أجل القدس. إصرار الفلسطينيين على تسميته \"حائط البراق\" هو رفض للرواية الصهيونية. الحائط، في نظرهم، هو جدار إسلامي، جزء من الأقصى، اغتُصب وهُدّمت حارته. تذكر المصادر الشفوية أسماء عائلات حارة المغاربة التي ما زالت لاجئة، والتي تطالب بحق العودة إلى بيوتها المهدمة. (مصادر: \"القدس: تاريخ مدينة\" – د. رشيد الخالدي، أرشيف مركز العودة الفلسطيني، مقابلات مع أهالي حارة المغاربة المهجرة – أرشيف فلسطين).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"حائط البراق ليس مجرد حجارة صامتة، بل هو ساحة صراع الروايات. الرواية الفلسطينية تؤكد أنه جدار إسلامي وقفي، جزء لا يتجزأ من المسجد الأقصى، ارتبط بالإسراء والمعراج، وهو اليوم مسلوب بفعل الاحتلال الذي دمر الحي الملاصق له لطمس هويته العربية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"الأماكن المقدسة في القدس\" – د. خالد عوض، \"وثائق الأوقاف القدسية\""]'::jsonb,'["هيرودي","روماني","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-9b42bff63df0','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','خان تجاري قرب باب الخليل.','[]'::jsonb,'["Riwaq registry"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-4bbdf07d8d66','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','أحد أسواق القدس التاريخية، بُني في زمن السلطان قلاوون.','[{"title":"الوصف المعماري","draft_text":"سوق القطانين (سوق تجار القطن) هو أحد أجمل الأسواق التاريخية في القدس. يقع في قلب البلدة القديمة، ويمتد من جهة الشمال إلى بوابة ضخمة تفتح مباشرة على ساحات الحرم القدسي الشريف (باب القطانين). السوق مسقوف بأقبية حجرية متقاطعة، وفي وسطه حمام تقليدي (حمام العين). النوافذ العلوية تسمح بدخول أشعة الشمس بشكل درامي يبرز جمال الحجر. الرواية المحلية ترى فيه تحفة معمارية تجمع بين الوظيفة التجارية والجمالية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البناء المملوكي","draft_text":"بناه الأمير المملوكي تنكز الناصري نائب الشام في عهد السلطان الناصر محمد بن قلاوون عام 1336م. كان تنكز محباً للعمران، وبنى عدة مشاريع في القدس. السوق لم يكن مجرد مكان لبيع القطن، بل كان جزءاً من وقف كبير يخصص ريعه للمدرسة التنكزية ودار الحديث القريبتين. هذا التكامل بين السوق والمدرسة والمسجد هو نموذج للمدينة الإسلامية حيث العبادة والعلم والتجارة في نسيج واحد.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الحكاية الاقتصادية","draft_text":"القطن كان محصولاً استراتيجياً في فلسطين المملوكية، يُزرع في غور الأردن ويُباع في أسواق القدس قبل تصديره إلى أوروبا عبر موانئ غزة ويافا. سوق القطانين كان مركز هذه التجارة. وثائق المحكمة الشرعية تذكر تجار القطن من العائلات المقدسية والخليلية والنابلسية، وتوضح كيف كان السوق مكاناً للقاء والتبادل التجاري بين فلسطين والعالم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"اليوم","draft_text":"السوق اليوم لا يزال يعمل، لكنه تحول إلى سوق للحرف اليدوية والتحف الشرقية. العائلات الفلسطينية المقدسية ما زالت تملك حوانيت فيه. الرواية الفلسطينية الحية هنا هي رواية التمسك بالأرض والمهنة رغم كل ضغوط التهويد والاستيطان.\n\n(المصادر: سجلات محكمة القدس الشرعية، كتاب \"أسواق القدس\" – أمانة القدس).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"أسواق القدس\" – أمانة القدس"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-8d297f3c37a9','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','كنيسة عند سفح جبل الزيتون، تضم قبر مريم العذراء بحسب التقليد المسيحي.','[{"title":"الموقع في وادي قدرون","draft_text":"عند سفح جبل الزيتون الشرقي، في عمق وادي قدرون، تقع كنيسة قبر السيدة مريم. للوصول إليها، ينزل الزائر 47 درجة حجرية إلى سرداب تحت الأرض، وكأنه يهبط إلى أحشاء الأرض ليقابل سراً مخبأ. المكان ليس كنيسة مرتفعة شاهقة، بل مغارة متواضعة. هذا التواضع المعماري يعكس شخصية صاحبة المكان: العذراء مريم، الأم المتواضعة التي عاشت وماتت في هدوء بعيداً عن الأضواء. الرواية الفلسطينية المحلية تحب هذا المكان بالذات لأنه يذكر الفلاحين ببيوتهم المتواضعة المنحوتة في الصخر.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"رواية الموت والدفن","draft_text":"بحسب التقاليد المسيحية الشرقية التي يتبناها مسيحيو فلسطين، عاشت مريم بعد صلب ابنها في رعاية يوحنا الحبيب في القدس، وماتت هناك. دُفنت في هذه المغارة في وادي قدرون من قبل الرسل. بعد ثلاثة أيام، فُتح القبر فلم يُعثر على جسدها، بل ورداً وريحاناً، مما يؤكد صعودها إلى السماء بالنفس والجسد (عيد الرقاد). هذه الرواية الشرقية تختلف قليلاً عن الرواية الكاثوليكية التي تذكر انتقالها من أفسس، لكنها متجذرة في التربة المقدسية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البناء البيزنطي والصليبي","draft_text":"بُنيت أول كنيسة فوق المغارة في القرن الخامس الميلادي، خلال العصر البيزنطي، بشكل دائري فوق القبر. دمرها الفرس ثم أعاد الصليبيون بناءها بشكلها الحالي في القرن 12، مع درج النزول الطويل والواجهة الحجرية الجميلة. دُفن فيها ملوك صليبيون مثل بلدوين الثاني ومليساندا، مما أضفى عليها أهمية سياسية أيضاً. بعد صلاح الدين، لم تتعرض الكنيسة لتدمير، واستمرت مقصداً للحجاج المسيحيين والمسلمين على السواء؛ فالعذراء مريم مكرمة في القرآن أيضاً بصفتها السيدة الطاهرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الذاكرة المحلية","draft_text":"في الرواية الفلسطينية الشفوية، تُعرف المغارة ببساطة بـ\"قبر مريم\". النساء المقدسيات المسيحيات والمسلمات كن يزرن المكان للتبرك وطلب الشفاعة، خاصةً في أمور الحمل والولادة. هذه الممارسة الشعبية تجعل من مريم شخصية حية في الوجدان الفلسطيني، وليست مجرد أثر تاريخي. الموقع اليوم تحت رعاية بطريركية الروم الأرثوذكس والأرمن، وتُقام فيه الصلوات يومياً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"قبر السيدة مريم هو أكثر الأماكن حميمية في القدس. إنه لا يروي قصة لاهوتية مجردة، بل قصة أم ودّعت الحياة بين أحبائها. الرواية الفلسطينية تجعله مكاناً للتعزية والتواصل الإنساني مع المقدس، بعيداً عن تعقيدات اللاهوت.\n\n(المصادر: \"دليل الأماكن المقدسة\" – مطرانية الروم الأرثوذكس، \"مريم في التراث الفلسطيني\" – د. فيرا سمعان).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"الأراضي المقدسة\" – الفرنسيسكان، \"دليل كنائس القدس\""]'::jsonb,'["بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f7553f79288f','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مجموعة قصور وأسبلة ومدارس منها المدرسة الطشتمرية ودار الحديث.','[{"title":"شارع الواد: شريان القدس المملوكي","draft_text":"شارع الواد هو الشارع الرئيسي الذي يخترق البلدة القديمة من باب العامود شمالاً إلى الحرم القدسي جنوباً. على جانبيه، قام المماليك (1250-1517م) ببناء سلسلة مذهلة من القصور والمدارس والخوانق (للمتصوفة) والأربطة. هذا الشارع ليس مجرد ممر، بل متحف مفتوح للعمارة المملوكية، والرواية الفلسطينية تراه كدليل حي على أن القدس كانت، وستبقى، مدينة إسلامية الحضارة والعمران.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"نماذج معمارية","draft_text":"المدرسة الطشتمرية: بناها الأمير المملوكي طشتمر العلائي عام 1382م. واجهتها الحجرية المشذبة بخطوط حمراء وبيضاء (الأبلق) تلفت الأنظار. كانت المدرسة تدرس الفقه الشافعي، وأوقفت عليها حوانيت في السوق المجاور لضمان استمراريتها المالية.\n\nدار الحديث التنكزية: بناها الأمير تنكز الناصري عام 1328م. كانت متخصصة في تعليم الحديث النبوي. مدخلها الضخم وبوابتها النحاسية المزخرفة تدل على أهميتها. الرواية المحلية تروي أن طلاب العلم كانوا يأتونها من كل أنحاء العالم الإسلامي.\n\nخانقاه صلاح الدين: بناها صلاح الدين الأيوبي لكن المماليك وسعوها. كانت مركزاً للمتصوفة الذين ينقطعون للعبادة بجوار الأقصى.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الحياة اليومية في العصر المملوكي","draft_text":"سجلات المحكمة الشرعية في القدس تقدم تفاصيل حية عن هذه المباني: عقود إيجار الحوانيت، أسماء الطلاب والمدرسين، ومخصصات الطعام للصوفية. لم تكن هذه المباني مجرد حجارة، بل كانت مراكز إشعاع فكري وروحي. الرواية الفلسطينية تستذكر أن هذه المدارس والخوانق هي التي حافظت على هوية القدس الإسلامية حين كانت محاصرة بممالك صليبية وغزوات مغولية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الإهمال والترميم","draft_text":"اليوم، بعض هذه القصور تحول إلى منازل سكنية لعائلات مقدسية، وبعضها الآخر مهمل. مؤسسة رواق (مركز المعمار الشعبي) قامت بترميم عدد منها للحفاظ على الإرث المملوكي. الرواية الفلسطينية المعاصرة تنظر إليها كجزء من النضال ضد تهويد القدس؛ فكل حجر يُرمم هو مقاومة لمحو الهوية.\n\n(المصادر: \"تاريخ القدس\" – مجير الدين الحنبلي، أرشيف رواق، سجلات محكمة القدس الشرعية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"الآثار المملوكية في فلسطين\" – د. عبد الله عطيات"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-83d3025c4675','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بنيت على أنقاض حصن هيرودي، جددها صلاح الدين والمماليك والعثمانيون، ودُعيت ببرج داود خطأ.','[{"title":"الموقع والتسمية المضللة","draft_text":"تقع القلعة قرب باب الخليل (باب يافا)، عند أعلى نقطة في البلدة القديمة للقدس. اسمها العربي الشائع \"قلعة القدس\"، لكنها تُعرف خطأً باسم \"برج داود\". هذه التسمية لا علاقة لها بالنبي داود، بل هي من اختراع الصليبيين في القرن 12م، الذين ظنوا أن أحد أبراجها هو برج النبي داود المذكور في المزامير. الرواية الفلسطينية تصحح: لا أثر للنبي داود هنا، والقلعة هي بناء روماني-أيوبي-مملوكي-عثماني تراكمي. استخدام الاسم \"برج داود\" اليوم هو جزء من محاولة تهويد المكان وربطه قسراً بالتاريخ اليهودي، في حين أن الاسم العربي الأصيل هو \"القلعة\" فقط. (مصدر: \"قلاع فلسطين\" – د. يوسف النتشة، مطبوعات رواق).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الجذور: هيرودس والرومان","draft_text":"الموقع الاستراتيجي كان معروفاً منذ القدم. بنى الملك هيرودس الكبير (القرن الأول ق.م) قصراً محصناً هنا أسماه \"قصر هيرودس\"، بأبراج ثلاثة أطلق عليها أسماء أحبائه: فصائيل (أخيه)، وهيبيكوس (صديقه)، ومريمان (زوجته التي قتلها). دمر الرومان المدينة عام 70م، لكنهم أبقوا على الأبراج لتكون حصناً للكتيبة الرومانية العاشرة (Legio X Fretensis) التي حكمت القدس المدمرة. أساسات هذه الأبراج لا تزال موجودة في القلعة الحالية، خاصةً قاعدة \"برج فصائيل\" الضخمة التي تُعتبر قلب القلعة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الأمويون والعباسيون: الإهمال النسبي","draft_text":"بعد الفتح الإسلامي، لم تعد القدس عاصمة إدارية (حلت محلها الرملة)، ففقدت القلعة أهميتها العسكرية المركزية. لكن المصادر تشير إلى أن الأمويين أضافوا تحصينات، واستخدمت فيما بعد كسجن ودار إمارة صغيرة في العصر العباسي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الأيوبيون: إعادة التحصين","draft_text":"بعد تحرير القدس من الصليبيين عام 1187م، أدرك صلاح الدين الأيوبي أهمية الموقع الدفاعي للقلعة، فأمر بإعادة بنائها وتحصينها لمواجهة أي هجوم صليبي مضاد. أضاف خندقاً عميقاً من جهة الغرب والشمال (وهو الخندق الذي كان موجوداً حتى أواخر العصر العثماني وردمه البريطانيون). وأقام فيها حامية عسكرية إسلامية. شقيقه الملك العادل أكمل العمل.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المماليك: العمارة الباقية","draft_text":"الشكل المعماري الحالي للقلعة يعود بشكل رئيسي للعصر المملوكي. بعد تحرير عكا وطرد الصليبيين نهائياً (1291م)، اهتم المماليك بتحصين المدن الداخلية خوفاً من غزوات المغول. السلطان الناصر محمد بن قلاوون (القرن 14) هو من بنى معظم الجدران والأبراج والخنادق التي نراها اليوم. أضاف مسجداً داخل القلعة، وحولها إلى ثكنة عسكرية وسجن للأسرى. الرواية الفلسطينية تحفظ أسماء أمراء مماليك نقشوا أسماءهم على حجارة القلعة، مما يدل على اعتزازهم بدورهم في حماية القدس. (مصدر: \"تاريخ القدس\" – مجير الدين الحنبلي).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العثمانيون: المئذنة الرمز","draft_text":"السلطان سليمان القانوني، في مشروعه الكبير لتحصين القدس وبناء سورها (1535-1538)، جدد القلعة وأضاف لها أيقونتها: المئذنة العثمانية الشاهقة. هذه المئذنة، التي ترتفع فوق برج فصائيل، أصبحت رمزاً للمدينة المقدسة في كل الصور واللوحات. العثمانيون استخدموا القلعة مقراً للحامية، وليس للسلطة المدنية (التي كانت في السراي). ظلت القلعة مركزاً عسكرياً، وسُميت \"قلعة باب الخليل\" نسبة للباب المجاور.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الحديث: من معسكر إلى متحف","draft_text":"في زمن الانتداب البريطاني، خرجت القلعة عن الخدمة العسكرية وتحولت إلى متحف. بعد 1948، سيطر الأردن على القدس الشرقية وجعلها متحفاً للآثار الفلسطينية. بعد 1967، احتلتها إسرائيل وحولتها إلى \"متحف برج داود لتاريخ القدس\". وهنا تبرز الرواية المضادة: المتحف الحالي يقدم سردية تاريخية تركز على التاريخ اليهودي وتهش الوجود العربي الإسلامي. الرواية الفلسطينية تؤكد أن غالبية آثار القلعة هي رومانية وإسلامية، وأن أبرز معالمها (المئذنة) عثماني.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"القلعة هي حارسة القدس الغربية، بُنيت بأيادٍ رومانية، وحُصنت بأيادٍ أيوبية ومملوكية، وتوجت بمئذنة عثمانية، وهي تشهد على أن الدفاع عن القدس كان ولا يزال مهمة إسلامية فلسطينية.\n\n(مصادر عامة: \"بلادنا فلسطين\" – مصطفى الدباغ، \"دليل أهم معالم القدس\" – مؤسسة إحياء التراث، Riwaq Registry).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"قلاع فلسطين\" – د. يوسف النتشة، Riwaq"]'::jsonb,'["روماني","بيزنطي","أيوبي","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-431ed266867b','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','أقدس موقع مسيحي، بنتها القديسة هيلانة في القرن الرابع، وتضم قبر المسيح.','[{"title":"الموقع والتأسيس","draft_text":"تقع كنيسة القيامة في قلب البلدة القديمة للقدس، في الحي المسيحي، على بُعد أمتار من المسجد الأقصى. بُنيت فوق الجلجلة، الموقع الذي يُعتقد أن المسيح صُلب فيه ودُفن وقام من بين الأموات. هذا التداخل بين الصلب والقيامة في مكان واحد هو ما يجعل كنيسة القيامة فريدة بين كنائس العالم؛ فهي ليست مجرد كنيسة، بل محجة تجمع أخطر محطات الآلام والقيامة. الرواية الفلسطينية المسيحية تسميها \"كنيسة القيامة\"، بينما تُعرف في الغرب باسم \"كنيسة القبر المقدس\" (Church of the Holy Sepulchre)، وهو اختلاف في التسمية يعكس اختلافاً في التركيز اللاهوتي؛ فالمسيحيون الفلسطينيون يركزون على القيامة لا الموت.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"ما قبل الكنيسة: محجر ومقبرة","draft_text":"الموقع كان في الأصل محجر حجارة مهملاً خارج أسوار القدس في القرن الأول الميلادي، وكان يُستخدم أيضاً كمقبرة. الأناجيل تذكر أن المسيح صُلب خارج السور في مكان يُدعى \"الجلجلة\" (مكان الجمجمة)، ودُفن في قبر حجري قريب. الرواية الفلسطينية المحلية تروي أن هذه المنطقة كانت أرضاً مكشوفة قاحلة، وأن القبر كان ملكاً ليوسف الرامي، وهو رجل من الرامة (قضاء القدس)، مما يعطي للقصة بعداً فلسطينياً محلياً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البناء البيزنطي: هيلانة وقسطنطين","draft_text":"بعد انتصار الإمبراطور قسطنطين على منافسه ليسينيوس (324م)، تبنّى المسيحية ديناً للإمبراطورية. والدته القديسة هيلانة (حوالي 326م) قامت برحلة حج إلى القدس بحثاً عن الصليب. الرواية الكنسية الفلسطينية تروي أن هيلانة، بإرشاد من مسيحيي القدس المحليين، وجدت ثلاثة صلبان في مغارة تحت معبد روماني كان قد بناه هادريان فوق الجلجلة لإخفاء المكان المقدس. للتحقق من الصليب الحقيقي، لمسته بجسد مريض فشُفي، فأمرت بهدم المعبد الروماني وبناء الكنيسة. هذه القصة، بغض النظر عن دقتها التاريخية الكاملة، تؤكد حقيقة أن المسيحيين الفلسطينيين هم من حافظوا على ذاكرة المكان طوال 300 عام بين الصلب والبناء، وهم من أرشدوا هيلانة إليه. هذا عنصر جوهري في الرواية الفلسطينية: استمرارية الوجود المسيحي المحلي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة الأصلية والتدمير","draft_text":"الكنيسة الأصلية التي بناها قسطنطين كانت بازيليكا ضخمة تضم ثلاث مناطق: كنيسة الشهادة (مارتيريوم)، وساحة مكشوفة حول الجلجلة، والقبر المقدس داخل قبة مستديرة (الأنسطاسيس). هذه التحفة المعمارية تعرضت للتدمير على يد الفرس الساسانيين عام 614م، ثم أُحرقت بالكامل بأمر الخليفة الفاطمي الحاكم بأمر الله عام 1009م، في واحدة من أحلك فترات العلاقات الإسلامية المسيحية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"إعادة البناء الصليبية والتسامح الأيوبي","draft_text":"أعاد البيزنطيون بناء الكنيسة جزئياً، لكن التغيير الأكبر حدث مع الصليبيين (القرن 12). قاموا بتوحيد جميع المواقع المقدسة تحت سقف واحد، وأضافوا الأجراس والواجهة الرومانسكية. بعد تحرير القدس على يد صلاح الدين الأيوبي عام 1187م، أُغلقت الكنيسة لفترة وجيزة، لكنه أعاد فتحها أمام الحجاج المسيحيين. الرواية الفلسطينية تفخر بأن صلاح الدين رفض هدم الكنيسة كما طلب بعض مستشاريه، قائلاً: \"لا نُعطيهم ذريعة ليقولوا إنا هدمنا كنائسهم كما هدموا مساجدنا\". بل أكثر من ذلك، أُسندت حراسة الكنيسة لعائلة فلسطينية مسلمة هي عائلة جودة (مفاتيح الكنيسة)، وعائلة نusseibeh (حفظ النظام داخلها)، وهما عائلتان مقدسيتان مسلمتان تتوارثان هذه المهمة حتى اليوم. هذا التقليد الفريد، حيث يسلم مسلم فلسطيني مفتاح أقدس كنيسة في العالم لراهب مسيحي كل صباح، هو أبلغ تعبير عن التعايش الفلسطيني. (مصدر: \"حراس القبر المقدس\" – د. مازن جودة، أرشيف العائلة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الوضع الراهن والنزاعات","draft_text":"منذ العصر العثماني، تخضع الكنيسة لـ \"الوضع الراهن\" (Status Quo)، وهو اتفاق معقد بين الطوائف المسيحية (الروم الأرثوذكس، اللاتين الكاثوليك، والأرمن) لتقاسم أجزاء الكنيسة وساعات الصلاة. أي تغيير طفيف يثير نزاعاً. الرواية الفلسطينية المحلية تروي قصة \"السلم الثابت\" الموضوع عند إحدى نوافذ الكنيسة منذ القرن 18؛ لم يحركه أحد لأن أي طائفة تحركه تخرق الوضع الراهن. هذه القصة الطريفة تعكس جموداً إدارياً، لكنها تؤكد أيضاً أن الفلسطينيين، مسلمين ومسيحيين، هم من يضمنون استقرار هذا الموقع المقدس عبر العصور.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"كنيسة القيامة، في الرواية الفلسطينية، ليست مجرد موقع مسيحي عالمي، بل هي كنيسة فلسطينية محلية. مسيحيو القدس هم من حفظوا ذاكرتها، ومسلمو القدس هم من حمى مفاتيحها. هي شهادة حية على أن فلسطين هي مهد المسيحية الأول، وأن التعايش بين الأديان فيها ليس شعاراً بل ممارسة يومية عمرها ألف عام.\n\n(المصادر: \"تاريخ الكنائس في الأرض المقدسة\" – الأب عيسى مصلح، \"كنيسة القيامة\" – مطرانية الروم الأرثوذكس في القدس، أرشيف عائلة جودة المقدسية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تاريخ الكنائس في فلسطين\" – الأب عيسى مصلح، موسوعة \"المسيحية في الأرض المقدسة\""]'::jsonb,'["روماني","بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-3a3d3669f0ba','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مقام أثري في الطابق العلوي من بناية صليبية، تحول لمسجد في العهد الإسلامي.','[{"title":"موقع يروي قصة","draft_text":"يقع مقام النبي داوود في الطابق العلوي من بناء ضخم على قمة جبل صهيون، جنوب السور القديم للقدس، قرب باب صهيون. البناء في أصله كان كنيسة بيزنطية تذكارية للرسل، حولها الصليبيون لكنيسة كبيرة. لكن الرواية الفلسطينية الإسلامية هي التي تهيمن على الموقع اليوم: إنه \"مقام النبي داوود\"، حيث يُعتقد أن داود عليه السلام مدفون هنا.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الجدل حول القبر","draft_text":"لا يوجد دليل أثري قاطع على أن داود دُفن هنا تحديداً. المصادر التوراتية تشير إلى أنه دُفن في \"مدينة داود\"، وهي التلة المقابلة جنوب الأقصى. لكن الرواية الإسلامية الفلسطينية، منذ العصر الأموي على الأقل، ربطت هذا الموقع بداود. ربما كان السبب سياسياً في البداية (لإيجاد توازن مع المواقع المسيحية)، لكن مع الزمن ترسخت القدسية وأصبحت جزءاً من الإيمان الشعبي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي والمملوكي","draft_text":"في العصر الأيوبي والمملوكي، تحولت الكنيسة الصليبية في طابقها العلوي إلى مسجد ومقام. أُضيف المحراب، ووُضعت على القبر كسوة خضراء، وأصبح المقام جزءاً من الوقف الإسلامي. السلطان المملوكي المؤيد شيخ هو من قام بأعمال الترميم الكبرى في القرن 15. مجير الدين الحنبلي، مؤرخ القدس المقدسي، يذكره كأحد المقامات المعظمة في المدينة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النزاع الحديث","draft_text":"بعد نكبة 1948، سيطرت إسرائيل على جبل صهيون، وحولت الطابق السفلي إلى كنيس يهودي (قبر داود المزعوم)، بينما بقي الطابق العلوي مسجداً ومقاماً تحت سيطرة الأوقاف الإسلامية حتى 1967، ثم احتلته إسرائيل وحولته بالكامل. الرواية الفلسطينية ترفض هذا الاستيلاء وتعتبره جزءاً من مخطط تهويد القدس. الحاخامات اليهود أنفسهم منقسمون حول صحة القبر، لكن الاحتلال يستخدمه كأداة سياسية. العائلة الفلسطينية التي كانت ترعى المقام (آل الأنصاري) ما زالت تحتفظ بمفاتيحه القديمة وتطالب بإعادته.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"مقام النبي داوود هو مثال آخر على صراع الروايات في القدس. بالنسبة للفلسطينيين، هو مقام إسلامي لنبي مكرم، استُولي عليه بقوة الاحتلال. إعادته هي جزء من استعادة الهوية المقدسية المنهوبة.\n\n(المصادر: \"تاريخ القدس\" – مجير الدين الحنبلي، \"المقامات الإسلامية في فلسطين\" – د. يوسف النتشة، مقابلات مع عائلة الأنصاري – مركز العودة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"المسجد الأقصى والمقامات\" – د. حسن الكرمي"]'::jsonb,'["أموي","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-899e38be070d','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بناه الكنعانيون، تحول لكنيسة في العهد الروماني، ثم مسجد في الفتح الإسلامي. به مقامات الأنبياء إبراهيم وإسحق ويعقوب.','[{"title":"ما قبل البناء: قدسية الموقع","draft_text":"قبل أن يُبنى أي حجر في الحرم الإبراهيمي، كانت الأرض نفسها مقدسة. يُعتقد أن الموقع كان في الأصل معبداً كنعانياً، وهذا ليس انتقاصاً من قدسيته، بل تأكيد على عمق الجذور الروحية للمكان في أرض فلسطين. القصة التوراتية/القرآنية تروي أن النبي إبراهيم اشترى مغارة المكفيلة من عفرون الحثي، وهو رجل كنعاني من سكان البلاد الأصليين، ليدفن فيها زوجته سارة. هذا الفعل الشرائي بالغ الأهمية في الرواية المحلية؛ فهو يُظهر أن العلاقة مع المكان بدأت باحترام العرف والقانون المحلي، لا بالغزو أو الاستيلاء. هذا هو الأساس الذي بنى عليه الفلسطينيون روايتهم: نحن ورثة إبراهيم، ضيف الله، وورثة الحثيين الكنعانيين الذين باعوه الأرض.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة عبر العصور: تراكم لا إحلال","draft_text":"البناء الهيرودي الضخم (القرن الأول ق.م) الذي يحيط بالحرم اليوم بسوره الحجري المهيب (بطول 60 متراً وعرض 34 متراً) ليس بناءً يهودياً خالصاً. هيرودس كان أدومياً، عيّنه الرومان ملكاً على المنطقة. بنى هذا السور ليكون ضريحاً يضاهي أضرحة الأباطرة، وليس معبداً يهودياً. هذا التدقيق مهم؛ فالرواية الفلسطينية ترى في هذا السور إرثاً أدومياً رومانياً، استخدمه البيزنطيون لاحقاً لبناء كنيسة كبرى في وسطه.\n\nمع الفتح الإسلامي، لم يهدم المسلمون الكنيسة بالكامل، بل حولوها إلى مسجد، مع إبقاء احترام المكان. في العصر الأيوبي، صلاح الدين الأيوبي، بعد تحرير الخليل من الصليبيين الذين كانوا يمنعون المسلمين من دخوله، أعاد المكان إلى قدسيته الإسلامية. أُضيف المنبر الخشبي البديع (الذي احترق عام 1969)، والمحراب، والمئذنتان. المماليك (الناصر محمد، قايتباي) هم من أضافوا الرواقين الشمالي والجنوبي، والأبواب المزخرفة، والمقامات المغطاة بالكسوة الفاخرة. هذا التطور يثبت أن الحرم الإبراهيمي كما نراه اليوم هو، في شكله المعماري النهائي، عمل فني إسلامي تراكمي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المجتمع الخليلي والإدارة الوقفية (القرن 12 – 20)","draft_text":"هنا يظهر الجانب الاجتماعي الغائب في الروايات الأخرى. منذ العهد الأيوبي، أنشئ للحرم وقف ضخم، يضم أملاكاً وقرى كاملة في محيط الخليل، لضمان استمرارية الصلاة والخدمة فيه. سجلات المحكمة الشرعية في الخليل (وهي كنز معلوماتي لا يُقدّر بثمن) تظهر تفاصيل دقيقة عن وظائف \"خدام الحرم\"، وكيف كانت عائلات مقدسية وخليلية بعينها تتوارث هذه المهام شرفاً. كان هناك \"شيخ الخدام\"، و\"قارئ البخاري\"، و\"السقاة\"، و\"الفرّاشون\". الحرم لم يكن مجرد مسجد، بل مؤسسة اقتصادية واجتماعية تشغل عشرات العائلات وتؤمن لهم رزقهم وتربطهم عضوياً بالمكان. الرواية الشفوية لأهالي الخليل، التي وثّقها د. منذر أبو حمدة، تروي أن المدينة كانت تحتفل بموسم الحرم في شهر رمضان، وتُقام الولائم في ساحاته، وكان المسيحيون يزورونه تبركاً أيضاً. (مصدر: سجلات محكمة الخليل الشرعية، أرشيف دار الوثائق في القدس).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النزاع الحديث وثبات الهوية","draft_text":"لا يمكن كتابة رواية الحرم الإبراهيمي المعاصرة دون التطرق لمجزرة 1994 التي ارتكبها مستوطن، وما تلاها من تقسيم زماني ومكاني جائر للحرم. هذه الأحداث ليست مجرد سياق سياسي، بل هي جزء من الذاكرة الجمعية الفلسطينية للمكان. الرواية الفلسطينية هنا تصبح رواية مقاومة للتهويد؛ فالحرم الذي كان يجمع المسلمين والمسيحيين في نسيج واحد، قُسّم بفعل الاحتلال. تمسك أهالي الخليل بدخول الحرم والصلاة فيه، رغم كل العراقيل، هو استمرار لتلك الرابطة العضوية التي استمرت قروناً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"الحرم الإبراهيمي هو تجسيد حي لشعار \"عيون فلسطينية\". إنه الموقع الذي يُرى من خلاله تاريخ فلسطين كاملاً: كنعاني يبيع أرضه لنبي، روماني يبني سوراً، مسيحيون يقيمون كنيسة، مسلمون يحولونها بحكمة إلى مسجد جامع، وعائلات فلسطينية تحرسه وتخدمه ستة قرون، ثم شعب بأكمله يتمسك به في وجه التقسيم. هذه هي الرواية متعددة الأبعاد التي يجب أن تُروى.\n\nبهذه الروايات الموسعة، تكون صفحة كل موقع في تطبيق \"عيون فلسطينية\" قد تحولت من مجرد \"بطاقة معلومات\" إلى \"فيلم وثائقي مقروء\". يمكن للتطبيق عرضها عبر تقسيم النص الطويل إلى بطاقات قابلة للطي (Expansion Tiles) تحت كل عصر، مع إبراز الشهادات الشفوية والاقتباسات من المصادر كمربعات مميزة بصرياً، ليشعر المستخدم أنه يغوص في تاريخ الموقع طبقة تلو الأخرى.\n\nاعتمد ذلك\n\nتم الاعتماد. سأبني على هذه المنهجية في الرواية التاريخية الموسعة لكل موقع يتم توثيقه في مشروع \"عيون فلسطينية\".\n\nالمنهجية المعتمدة للرواية الفلسطينية الموثّقة\n\nالمبادئ الأساسية\n\nالسرد المتعدد الأبعاد: لا نكتفي بسرد الأحداث السياسية، بل نغطي:\n\nالجانب الهندسي والمعماري\n\nالجانب الاجتماعي والاقتصادي (الأوقاف، الحرف، العائلات)\n\nالجانب الديني والروحي\n\nالجانب الإداري والقانوني (السجلات، الحقوق)\n\nالذاكرة الشفوية والتقاليد الشعبية\n\nالنزاعات الحديثة والتهديدات المعاصرة\n\nالتوثيق بالمصدر في المتن: كل معلومة رئيسية تُنسب لمصدرها داخل النص، وليس فقط في نهايته.\n\nالرواية المضادة: نقدم الرواية الفلسطينية التي تصحح التحريفات والمزاعم الإسرائيلية، دون أن نقع في الخطاب الدعائي. نعتمد على الوثائق والأدلة.\n\nالاستمرارية التاريخية: نظهر أن الموقع لم يكن \"ميتاً\" بين عصر وآخر، بل استمر استخدامه وإدارته من قبل السكان المحليين عبر كل العصور.\n\nتطبيق المنهجية على جميع المواقع\n\nسأبدأ الآن بتوسيع الروايات لباقي المواقع الرئيسية في المصفوفة، بنفس العمق الذي قدمناه لبرك سليمان والحرم الإبراهيمي. سأقدمها تباعاً:","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تاريخ الخليل\" – د. منذر أبو حمدة، \"المسجد الإبراهيمي\" – وزارة الأوقاف"]'::jsonb,'["كنعاني","روماني","أموي","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-6b6c5a396756','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','أزقة وحارات تاريخية (الشيخ، باب الزاوية، المشارقة)، خان شاهين، أسواق تقليدية.','[{"title":"التخطيط العمراني","draft_text":"البلدة القديمة للخليل ليست مجرد مجموعة بيوت، بل هي كائن حي عمراني. شوارعها الضيقة المتعرجة (الأزقة) صُممت عمداً لتوفير الظل وتوجيه الرياح. الحارات الرئيسية هي: حارة الشيخ (حول الحرم)، حارة المشارقة (نسبة للمهاجرين من المشرق)، حارة باب الزاوية، وحارة الأكراد. لكل حارة هويتها ومسجدها وساحتها الخاصة (الحوش). الرواية المحلية تروي أن الأزقة كانت تُغلق ليلاً ببوابات خشبية للأمان، وكان لكل حارة شيخ يحل النزاعات.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خان شاهين","draft_text":"في قلب البلدة القديمة، يقع خان شاهين، وهو خان تجاري ضخم بناه المماليك وجدده العثمانيون. كان يستقبل قوافل التجار القادمين من مصر والشام، وفيه غرف للإقامة ومخازن للبضائع وإسطبلات للخيل. اليوم، الخان مهمل جزئياً، لكنه يظل شاهداً على دور الخليل كمحطة تجارية رئيسية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"أسواق الخليل التقليدية","draft_text":"سوق العنب، سوق الخضار، سوق الصاغة (الذهب)... هذه الأسواق متخصصة ومتقابلة. ما يميز الرواية الفلسطينية هنا هو نظام \"الحسبة\" الذي كان يراقب الأسعار والموازين ويمنع الغش. سجلات المحكمة الشرعية تحوي عشرات القضايا ضد تجار خالفوا الأوزان، مما يدل على رقابة صارمة. (مصدر: \"الخليل: تاريخ وحضارة\" – د. عدنان أبو تبانه).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التهديدات المعاصرة","draft_text":"منذ احتلال 1967، وخاصة بعد إنشاء مستوطنة \"تل رميدة\" في قلب المدينة، تتعرض البلدة القديمة لضغوط هائلة. المستوطنون يحتلون البيوت، والحواجز العسكرية تقطع الأزقة، والتجار يهجرون الأسواق. الرواية الفلسطينية اليوم هي رواية صمود؛ لجنة إعمار الخليل تقوم بترميم البيوت القديمة، والعائلات الخليلية تصر على البقاء رغم المضايقات. كل بيت يُرمم هو تحدٍ للاحتلال. (مصدر: تقارير لجنة إعمار الخليل، مؤسسة أريج).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"خليل الرحمن\" – بلدية الخليل، Riwaq"]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f60be7cd7d5e','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','تعرض المسودة بيت أمر وخربة النبي متى كمسار يربط البلدة القديمة بالمعاصر والمقام والذاكرة المسيحية والإسلامية، مع حاجة إلى مراجعة أثرية دقيقة.','[{"title":"البلدة والتاريخ","draft_text":"بيت أمر بلدة قديمة شمال الخليل، اسمها آرامي يعني \"بيت آل عمرو\". فيها خربة أثرية تُعرف بخربة النبي متى، يُعتقد أنها مقام النبي متى (متياس) أحد تلاميذ المسيح.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المقام والذاكرة المسيحية الإسلامية","draft_text":"المقام بناء حجري بسيط، تزوره النساء للتبرك. الرواية المحلية لا تفرق بين قدسية إسلامية أو مسيحية؛ المكان مقدس لأنه مرتبط بنبي. هذا التداخل الديني هو سمة فلسطينية أصيلة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["إحالات الرواية الموسعة في الوثيقة المرجعية — تحتاج تحققاً ببليوغرافياً"]'::jsonb,'["روماني","بيزنطي","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-63c0ba59c24e','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','موقع مدينة الخليل القديمة، به طبقات أثرية هامة.','[{"title":"الموقع والاكتشاف","draft_text":"تل الرميدة هو تلة أثرية تقع في الجانب الشمالي الغربي من البلدة القديمة للخليل. هو موقع مدينة الخليل القديمة (الكنعانية والإسرائيلية). الحفريات الأثرية التي قامت بها بعثات أمريكية وفلسطينية كشفت عن طبقات استيطانية تعود للألف الثالث قبل الميلاد (العصر البرونزي المبكر). الرواية الفلسطينية تعتز بهذا الموقع لأنه يثبت أن الخليل مدينة كنعانية عربية في أصلها، عمرها أكثر من 5000 عام.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البوابات والأسوار","draft_text":"أهم ما كُشف في تل الرميدة هو بوابة المدينة الكنعانية الضخمة وبقايا السور. هذه البوابة تشبه بوابات مدن كنعانية أخرى مثل تل الجزر وتل مجدو، مما يؤكد وحدة الحضارة الكنعانية في فلسطين. الرواية المضادة ترفض الادعاءات الإسرائيلية التي تحاول حصر تاريخ التل في الحقبة التوراتية فقط؛ فالطبقات الكنعانية هي الأقدم والأكثر سمكاً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النبع المقدس","draft_text":"قرب التل، تقع \"عين جديجة\" (أو عين سارة)، وهي نبع ماء قديم يرجح أنه كان مركز العبادة الكنعاني المرتبط بالمدينة. المياه كانت مقدسة، والمدينة قامت حولها.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الصراع على التل","draft_text":"اليوم، تل الرميدة هو بؤرة استيطانية. أقام المستوطنون الإسرائيليون بؤرة استيطانية فوق التل الأثري نفسه، وهو انتهاك صارخ للقانون الدولي. الحفريات التي يقومون بها مشبوهة، ويُعتقد أنها تهدف للعثور على أي أثر \"يهودي\" لتبرير وجودهم، مع إهمال الطبقات الكنعانية والإسلامية. (مصدر: تقارير دائرة الآثار الفلسطينية، \"الخليل عبر العصور\" – جامعة الخليل).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"حفريات الخليل\" – دائرة الآثار الفلسطينية"]'::jsonb,'["برونزي","كنعاني","روماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-cd3be04163b6','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','تقدم المسودة حلحول بوصفها بلدة تاريخية شمال الخليل ترتبط بمقام النبي يونس وذاكرة محلية وموسمية تحتاج تدقيقاً ومصادر أصلية.','[{"title":"الموقع والتاريخ القديم","draft_text":"حلحول بلدة قديمة شمال الخليل، على الطريق الواصل إلى بيت لحم والقدس. اسمها كنعاني، ورد في سفر يشوع (15:58) كإحدى مدن جبال الخليل. فيها مقامات إسلامية عديدة، أشهرها مقام النبي يونس.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"مقام النبي يونس","draft_text":"يقع المقام على قمة جبل في حلحول. الرواية المحلية تؤكد أن النبي يونس (ذا النون) دُفن هنا بعد رحلة الحوت. المقام بناء ضخم من العصر المملوكي، جُدد في العهد العثماني، وله محراب ومنارة. كان محطة للقوافل بين القدس والخليل. الرواية الشعبية تضيف أن من زار المقام ودعا عنده استُجيب دعاؤه، مما جعله مزاراً مشهوراً. (مصدر: \"مقامات الأنبياء في فلسطين\" – د. أحمد حجازي، وزارة الأوقاف الفلسطينية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["إحالات الرواية الموسعة في الوثيقة المرجعية — تحتاج تحققاً ببليوغرافياً"]'::jsonb,'["كنعاني","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-2310c1600481','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','خان تجاري قديم في البلدة القديمة.','[]'::jsonb,'["Riwaq"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-c9ac723c0271','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مقام وقرية تاريخية، بها آثار رومانية.','[{"title":"دورا: مدينة العنب والتاريخ","draft_text":"دورا هي أكبر بلدات محافظة الخليل، تقع على هضبة مرتفعة جنوب غرب الخليل. اسمها مشتق من \"أدورايم\" الكنعانية، وتعني \"المساكن\". اشتهرت دورا منذ القدم بكروم العنب التي تحيط بها، وصناعة الدبس (دبس العنب) التي ما زالت حرفة تقليدية فيها.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خربة النبي نوح","draft_text":"قرب دورا، تقع خربة النبي نوح، وهي موقع أثري يضم مقاماً منسوباً للنبي نوح عليه السلام. الرواية المحلية تروي أن نوحاً دُفن هنا، وهناك روايات أخرى تذكر دفنه في العراق أو تركيا. بغض النظر عن صحة الدفن، فإن وجود مقام بهذا الاسم يؤكد أن الذاكرة الشعبية الفلسطينية ربطت هذه الأرض بقصص الأنبياء. المقام مبني بالحجر الكلسي الأبيض، وله قبة بسيطة. كان أهالي دورا يزورونه في المواسم ويقيمون عنده الذبائح والنذور. (مصدر: \"المقامات الدينية في الخليل\" – معهد أريج، شهادات شفوية من أهالي دورا).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"مسح الآثار في دورا\" – جامعة الخليل"]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
