insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-7532d020842e','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','أحد مقامات الخليل التاريخية.','[]'::jsonb,'["\"المقامات الدينية\" – أريج"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-37c8be50ce73','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','3 برك ضخمة جنوب بيت لحم، تزود القدس بالمياه عبر قنوات، عمّرها السلطان سليمان القانوني. (أنظر التفصيل السابق)','[{"title":"الموقع والجغرافيا (ما وراء الوصف)","draft_text":"لا يمكن فهم برك سليمان بمعزل عن التضاريس التي أوجدتها. تقع البرك في قاع وادي أرطاس الخصيب، المعروف بوفرة ينابيعه الدائمة مثل \"عين صالح\" و\"عين البورة\". هذا الموقع ليس مصادفة، بل هو نقطة تجميع طبيعية لمياه الأمطار والينابيع من مرتفعات بيت لحم والخليل قبل أن تشق طريقها في وادي الجوز (وادي النار) نحو غور الأردن.\n\nاختار المهندسون الرومان هذا الموقع تحديداً لأنه يمثل أعلى نقطة يمكن تجميع المياه فيها بكميات هائلة ثم إسالتها بقوة الانحدار الطبيعي عبر قنوات تمتد لعشرات الكيلومترات دون الحاجة إلى مضخات. هذا الفهم العميق لطبوغرافيا فلسطين هو جوهر العبقرية الهندسية هنا. الرواية المحلية تسمي هذه القنوات \"قناة السبيل\"، ولا تزال أجزاؤها المكشوفة تُظهر دقة البناء بالحجر المشذّب والمونة المقاومة للماء، وهي تقنية تناقلها المعماريون المحليون عبر الأجيال.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التسلسل التاريخي العميق والرواية الموثقة","draft_text":"العهد الروماني: البناء والتقنية (القرن الثاني – الرابع الميلادي)\n\nلم تكن البرك مجرد خزانات، بل جزءاً من منظومة هيدروليكية معقدة هي الأضخم في الشرق الأدنى القديم. تُظهر الحفريات الأثرية التي قامت بها سلطة الآثار الفلسطينية عام 2015 أن القناة السفلية كانت مبنية بأنفاق محفورة في الصخر وقناطر حجرية تُعبر الأودية. كُتب على أحد مقاطع القناة نقش لاتيني يعود للكوهورت العاشرة الرومانية (Legio X Fretensis) التي كانت تقيم في القدس، مما يؤكد أن الجيش الروماني هو من أشرف على هذا المشروع الحيوي لتزويد معسكراته والمدينة المقدسة بالمياه. وهنا تكمن الرواية المضادة: الاحتلال الروماني للمدينة هو الذي استدعى هذا المشروع الضخم، فالماء كان أداة سيطرة وليس خدمة فقط. (مصدر: تقرير حفريات 2015، ونقش لاتيني محفوظ في متحف إسرائيل).\n\nالعصران البيزنطي والإسلامي المبكر: القدسية والتوسع (القرن الخامس – العاشر)\n\nمع تحول فلسطين إلى مركز للحج المسيحي ثم الإسلامي، تضاعفت أهمية البرك. يذكر الحاج البيزنطي \"ثيودوسيوس\" (530م) في مذكراته \"بركاً عظيمة تروي القدس\". أما بعد الفتح الإسلامي، فيروي لنا الجغرافي المقدسي في كتابه \"أحسن التقاسيم في معرفة الأقاليم\" (985م) وصفاً دقيقاً لقناة عظيمة \"تأتي من جبال بيت لحم إلى برك في القدس عند باب المسجد\". المقدسي، وهو فلسطيني من القدس، لا يصفها كأثر غريب، بل كجزء حيوي من بنية المدينة التي يعرفها. هذا التأكيد على الاستمرارية هو جوهر الرواية الفلسطينية: المنشأة لم تتعطل بتبدل الحضارات، بل أدارها السكان المحليون وطوروها باستمرار. (مصدر: كتاب المقدسي، ومذكرات الحجاج البيزنطيين).\n\nالعصر العثماني: ذروة الازدهار والإدارة المحلية (القرن السادس عشر – التاسع عشر)\n\nهذا هو العصر الذهبي الذي ترويه الذاكرة الفلسطينية بوضوح. حين زار السلطان سليمان القانوني القدس، أدرك أن مشكلة المياه هي التحدي الأكبر. لم يكتفِ بترميم البرك، بل بنى قلعة عسكرية (قلعة البرك) لحمايتها من البدو وقطّاع الطرق، وجدّد القناة بالكامل حتى سبيل الحرم في القدس، حيث كانت المياه تتدفق بغزارة في سبيل شُيّد خصيصاً لهذا الغرض. لكن التفصيل الأهم الذي تحفظه سجلات المحكمة الشرعية في القدس (الطابو) هو نظام الإدارة. لم تكن الدولة هي المدير المباشر، بل أوقفت القرى المجاورة، وخاصة أرطاس، لصيانة البرك والقناة. أُنشئ وقف خاص تُصرف أمواله على العمال المحليين الذين توارثوا مهمة تنظيف القناة وتوزيع المياه. وهكذا، لم تكن البرك مشروعاً سلطوياً فوقياً، بل نسيجاً اقتصادياً واجتماعياً متشابكاً مع حياة الفلاحين. (مصدر: سجل رقم 27، محكمة القدس الشرعية، 1565م؛ وكتاب \"القدس في العهد العثماني\" لد. أحمد حجازي).\n\nالقرن العشرون: الحداثة والهجران والذاكرة\n\nمع بدء إنشاء شبكات المياه الحديثة في القدس زمن الانتداب البريطاني، فقدت البرك دورها الوظيفي تدريجياً. لكن الذاكرة الشفوية لا تزال حية. في أرشيف مشروع \"الرواية الفلسطينية\" (تسجيلات 1998)، يروي الحاج أبو علي من أرطاس: \"كنا نروي بساتيننا من البركة الثالثة، وكان لنا حق ماء مسجل بالطابو. جدي كان يطلع كل سنة مع رجال القرية ينظفوا القناة، وكانوا يمشوا فيها للقدس.. مشوار يومين\". هذه الشهادة تنقلنا من تاريخ الحكام إلى تاريخ الناس، وتؤكد أن المكان لم يكن مجرد حجارة وماء، بل كان إرثاً حياً من الحقوق والعمل والتقاليد. (مصدر: أرشيف فلسطين للنكبة والتراث).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الجوانب الهندسية والعمرانية","draft_text":"البركة الأولى (العليا) هي الأكبر وتستقبل المياه مباشرة من الينابيع. البركة الثانية تتوسطها، أما الثالثة فكانت مخصصة للزراعة المحلية غالباً. جدران البرك مبنية بنظام الحجر المشذّب والمائل قليلاً إلى الداخل لمقاومة ضغط الماء الهائل. وما زالت بقايا القنوات المغطاة بأقبية حجرية تثير إعجاب المهندسين حتى اليوم. قرب البرك، أنشأ العثمانيون قلعة مربعة الشكل ذات برج مراقبة، وهي مثال على العمارة العسكرية العثمانية المحلية، وقد استخدمت لحماية المنشأة الحيوية ولتكون مركزاً لجمع الضرائب على المياه.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"برك سليمان ليست مجرد أثر مائي، بل هي سجل حي لصراع الإنسان الفلسطيني مع الجغرافيا، وقدرته على ترويضها، وتحويلها إلى مصدر حياة وتعاون. إنها قصة حق مائي موروث، واقتصاد محلي، وعبقرية هندسية تراكمت عبر ألفي عام، وتوجتها الإدارة العثمانية بنظام وقفي جعل من كل فلاح في أرطاس شريكاً في إمداد القدس بالمياه. هذه هي الرواية التي ترويها الحجارة والمخطوطات والذاكرة الحية معاً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"أنظمة المياه في فلسطين\" – م. ناصر الدين، \"رحلة أوليا جلبي\""]'::jsonb,'["روماني","بيزنطي","أموي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f97aa993c98b','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','دير تاريخي يضم بئر ماء مقدسة.','[{"title":"الموقع والتسمية","draft_text":"يقع دير الجنة في بلدة الخضر، غرب بيت لحم. اسم البلدة \"الخضر\" مشتق من الخضر (القديس جاورجيوس في التقاليد المسيحية الشرقية، أو النبي إلياس/الخضر في التقاليد الإسلامية). الدير هو نموذج حي للتداخل الديني الفلسطيني: كنيسة للقديس جاورجيوس يزورها المسيحيون، ومقام للخضر يزوره المسلمون، في نفس البناء.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الرواية المشتركة","draft_text":"بحسب التقاليد المسيحية، جاورجيوس كان جندياً رومانياً فلسطينياً من اللد، استشهد في اضطهاد الإمبراطور دقلديانوس (303م). وبحسب التقاليد الإسلامية، الخضر هو \"العبد الصالح\" الذي ذكره القرآن دون اسم، وهو نبي أو ولي حي خالد. الشخصيتان اندمجتا في الذاكرة الشعبية الفلسطينية في شخصية واحدة: فارس مقدس يركب حصاناً ويحارب الشر وينصر المظلومين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الدير والمقام","draft_text":"الكنيسة الحالية بُنيت في القرن 17، لكن الموقع أقدم. في ساحة الدير، بئر ماء عميقة يعتقد الزوار أنها مقدسة وتشفي الأمراض. المسلمون يزورون المكان لتقديم النذور وإشعال الشموع، تماماً كما يفعل المسيحيون. هذا التداخل ليس توفيقاً لاهوتياً مصطنعاً، بل هو تعبير عضوي عن التدين الشعبي الفلسطيني الذي يوحد ولا يفرق. (مصدر: \"الأولياء والمقامات في فلسطين\" – د. شريف كناعنة، \"القديس جاورجيوس في التراث الفلسطيني\" – د. فيرا سمعان).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"المسيحية في الأرض المقدسة\""]'::jsonb,'["بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a8aeb054b451','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','دير أرثوذكسي في وادي قدرون، أسسه القديس سابا في القرن الخامس. دير يوناني أرثوذكسي في برية القدس.','[{"title":"الموقع: معلق بين السماء والأرض","draft_text":"يقع دير مار سابا في وادي قدرون (وادي النار) على بُعد 15 كيلومتراً شرق بيت لحم، في عمق برية القدس القاحلة. الدير معلق على حافة جرف صخري عمودي، يشبه عش النسر. الوصول إليه كان يتم بحبل وبكرة حتى العصر الحديث. هذا الموقع المتطرف لم يُختر عبثاً؛ فالنساك الذين بنوه كانوا يبحثون عن العزلة المطلقة والتأمل في الصحراء، حيث لا يصلهم صوت العالم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المؤسس: القديس سابا","draft_text":"أسس الدير القديس سابا (439-532م)، وهو راهب كبادوكي (من تركيا الحالية) قدم إلى فلسطين وعاش في برية القدس. جمع حوله مئات الرهبان، وبنى الدير كحصن للنسك والصلاة. سابا كان شخصية قوية؛ قاد وفداً من رهبان فلسطين إلى القسطنطينية للدفاع عن العقيدة الأرثوذكسية أمام الإمبراطور. مات في الدير ودُفن فيه، وما زال جسده محفوظاً في كنيسة الدير حتى اليوم. الرواية المحلية ترى فيه أحد آباء الكنيسة الفلسطينية، رغم أنه لم يولد في فلسطين، لأنه أحبها وعاش ومات فيها.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"نظام الحياة في الدير","draft_text":"دير مار سابا هو دير \"لافرا\"، أي دير نساك متجمعين. الرهبان يعيشون في قلالي (غرف) منحوتة في الصخر، ولا يأكلون اللحم أبداً، ويصومون معظم أيام السنة. النساء ممنوعات من دخول الدير حتى اليوم، باستثناء برج صغير خارج السور يُسمى \"برج النساء\"، حيث يمكن للزائرات المبيت. هذه القوانين الصارمة جعلت من مار سابا أحد أكثر الأديرة تحفظاً في العالم، وهو يمثل استمرارية حية للتقاليد الرهبانية الفلسطينية الباكرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المخطوطات والمكتبة","draft_text":"كان دير مار سابا في القرون الوسطى مركزاً فكرياً. فيه أكبر مكتبة مخطوطات في فلسطين بعد مكتبة دير سانت كاترين في سيناء. العديد من المخطوطات السريانية واليونانية والعربية محفوظة فيه. في القرن 19، اشترت مكتبة روسيا القيصرية مجموعة ضخمة من مخطوطاته (مجموعة مار سابا)، مما أثار جدلاً حول سرقة التراث الفلسطيني. (مصدر: \"مكتبة مار سابا\" – د. يوسف زيدان).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي: الحماية والاحترام","draft_text":"بعد الفتح الإسلامي، أُعطي الدير عهداً بالحماية. الخلفاء الراشدون والأمويون والعباسيون احترموا حرمة الدير، وكانت القبائل العربية البدوية في المنطقة تحميه ولا تقترب منه. هذا التعايش بين الرهبان والبدو هو جزء من الرواية الفلسطينية التي تؤكد أن المسيحية الفلسطينية لم تكن جزيرة معزولة، بل كانت جزءاً من النسيج الاجتماعي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"دير مار سابا هو شاهد على أقصى درجات الإيمان والتقشف. إنه يثبت أن فلسطين لم تكن مجرد ممر للأنبياء، بل كانت مختبراً للتجربة الروحية العميقة. الرهبان الذين علقوا حياتهم على جرف صخري هم جزء من تراث هذه الأرض بقدر ما هم جزء من تراث المسيحية.\n\n(المصادر: \"دليل الأديرة الفلسطينية\" – مطرانية الروم الأرثوذكس، \"القديس سابا ورهبنة برية القدس\" – د. حنا كتناشو، أرشيف دير مار سابا).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"دليل الأديرة الفلسطينية\" – المركز الأرثوذكسي","\"دليل أديرة فلسطين\" – مطرانية الروم"]'::jsonb,'["بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-88fede7b6df0','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مصاطب زراعية رومانية وقنوات ري، موقع تراث عالمي (اليونسكو).','[{"title":"الجغرافيا والموقع","draft_text":"تقع بتير على بُعد 7 كيلومترات غرب بيت لحم، على سفح جبل يطل على وادي الصرار (وادي النطرون). تضاريسها شديدة الانحدار، مما دفع سكانها منذ آلاف السنين إلى بناء المصاطب (المدرجات) الزراعية الحجرية، وهي تحفة هندسية زراعية تجعل الجبال سلالم خضراء. في عام 2014، أُدرجت بتير على قائمة التراث العالمي لليونسكو، ليس كموقع أثري واحد، بل \"كمشهد ثقافي حي\" يمثل تعايشاً فريداً بين الإنسان والطبيعة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التاريخ القديم: بتر الرومانية","draft_text":"كانت بتير تُعرف في العصر الروماني باسم \"بيتار\" (Bethar)، وكانت آخر معاقل ثورة باركوخبا اليهودية ضد الرومان (132-135م). لكن الرواية الفلسطينية تصحح: بعد تدمير الرومان لبيتار، سكن الموقع سكان كنعانيون ورومان ثم بيزنطيون، وتحولت إلى قرية زراعية مزدهرة. الآثار الرومانية في بتير تشمل بقايا قنوات مياه وحمامات رومانية، مما يدل على استمرارية السكن وليس هجرة الموقع.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"نظام الري العثماني: عدالة الماء","draft_text":"أثمن ما في بتير هو نظام الري التقليدي الذي ما زال يعمل حتى اليوم. ينبع الماء من عين بتير (نبع القرية)، ثم يجري في قنوات حجرية مكشوفة تتفرع إلى ثمانية أودية. توزيع المياه يتم بنظام \"الحصص\" أو \"المناوبة\" (بالدور)، حيث يُعطى كل حقل حصته من الماء لمدة ساعة أو ساعتين أسبوعياً حسب نظام عرفي عمره مئات السنين. سجلات الطابو العثمانية وثّقت هذه الحقوق المائية. الرواية المحلية تروي أن هذا النظام كان عادلاً لدرجة أنه لم تقم أي نزاعات على الماء في تاريخ بتير. (مصدر: \"أنظمة المياه في فلسطين\" – م. ناصر الدين، اليونسكو – ملف بتير 2014).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"سكة حديد الحجاز والانتداب البريطاني","draft_text":"يمر بجوار بتير خط سكة حديد الحجاز الذي بناه العثمانيون (1908)، ثم سيطر عليه البريطانيون. بتير كانت محطة صغيرة على هذا الخط. الرواية الشفوية تروي أن الفلاحين كانوا يبيعون التين والعنب للمسافرين في القطار المتجه إلى القدس.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النكبة والحدود الملتهبة","draft_text":"بعد نكبة 1948، وقعت بتير تحت الحكم الأردني، لكن خط الهدنة (الخط الأخضر) مرّ تماماً بجوار القرية. بتير أصبحت قرية حدودية، وسكانها صمدوا على أرضهم رغم كل الحروب. بعد 1967، احتلت إسرائيل الضفة الغربية، لكن بتير بقيت رمزاً للصمود الزراعي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التهديد المعاصر: جدار الفصل","draft_text":"في العقد الأخير، هدد جدار الفصل العنصري الإسرائيلي بعزل بتير عن أراضيها الزراعية وقطع نظام الري القديم. نضال أهالي بتير، بدعم من مؤسسات فلسطينية ودولية، أوقف بناء الجدار مؤقتاً، وتحولت القضية إلى محكمة العدل الإسرائيلية التي أمرت بإعادة تخطيط الجدار. هذا النضال البيئي والقانوني هو أحدث فصول الرواية الفلسطينية لبتير: قرية صغيرة تقاوم أكبر جيش في الشرق الأوسط، ليس بالسلاح، بل بالحجر والماء والذاكرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"بتير هي فلسطين المعلقة على الجبال. إنها قصة فلاحين حولوا الصخر إلى جنة، واخترعوا نظاماً للماء هو الأعدل في العالم. هي شهادة على أن الفلسطيني ليس مجرد ساكن في هذه الأرض، بل هو صانعها وبانيها وحاميها.\n\n(المصادر: ملف بتير في اليونسكو، أرشيف بلدية بتير، \"المصاطب الزراعية في فلسطين\" – معهد أريج، شهادات أهالي بتير – مشروع الرواية الشفوية الفلسطينية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"بتير: المشهد الثقافي\" – اليونسكو"]'::jsonb,'["روماني","بيزنطي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-133155518939','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','قصر جبلي بناه هيرودس الكبير، تحول لحصن.','[{"title":"الموقع والبناء","draft_text":"يقع هيروديون (جبل فريديس) على بُعد 6 كيلومترات شرق بيت لحم، وهو الجبل الوحيد في فلسطين الذي شكله الإنسان بالكامل. بناه الملك هيرودس الكبير (37-4 ق.م) كقصر وحصن وضريح له. إنه تل صناعي مخروطي الشكل، يشبه بركاناً خامداً. قمة التل كانت قصراً فخماً بأبراج وأروقة وحدائق معلقة، وفي أسفله مدينة صغيرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة والهندسة","draft_text":"هيروديون هو تحفة هندسية. بُني بسكب طبقات من التراب والحجر فوق تل طبيعي صغير حتى وصل ارتفاعه إلى 100 متر. داخل التل الصناعي، حُفرت خزانات مياه ضخمة، وأقبية، ومخازن أسلحة. القصر العلوي كان دائرياً بقطر 63 متراً، بأربعة أبراج (أحدها ما زال قائماً). في أسفل التل، كانت هناك بركة سباحة ضخمة محاطة بالأعمدة، وحدائق، ومبانٍ إدارية. هذا المزيج من الترف والعسكرة يعكس شخصية هيرودس: ملك مهووس بالعظمة والخوف معاً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الثورة اليهودية الكبرى","draft_text":"خلال الثورة اليهودية ضد الرومان (66-70م)، سيطر الثوار على هيروديون واستخدموه كقاعدة. لكن الرومان استعادوه بسهولة نظراً لموقعه المنكشف. الرواية الفلسطينية ترى في هذه الأحداث طبقة عابرة في تاريخ الموقع، وتؤكد أن الاستيطان البشري في المنطقة أقدم وأوسع من الحقبة الهيرودية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"قبر هيرودس","draft_text":"ظل قبر هيرودس مفقوداً حتى عام 2007، حين اكتشفه البروفيسور إيهود نيتزر في سفح التل. كان القبر فخماً جداً، مبني بالحجر الأبيض المزخرف. لكن الرومان حطموه بالكامل. اكتشاف القبر كان مهماً، لكنه لم يغير الرواية الفلسطينية عن الموقع: إنه أثر هيرودي-روماني، لا علاقة له بالتاريخ اليهودي المقدس.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الوضع الراهن","draft_text":"هيروديون اليوم يقع في المنطقة (ج) تحت السيطرة الإسرائيلية الكاملة، وحُول إلى \"منتزه وطني\" إسرائيلي يمنع الفلسطينيين من الوصول إليه بحرية. الرواية الفلسطينية تطالب بحماية الموقع وإدارته من قبل وزارة السياحة والآثار الفلسطينية، كجزء من التراث الثقافي الوطني.\n\n(المصادر: \"آثار هيرودس\" – إيهود نيتزر، تقارير سلطة الآثار الفلسطينية، \"هيروديون: تاريخ وحفريات\" – الجامعة العبرية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"آثار هيرودس\" – إيهود نيتزر، دائرة الآثار"]'::jsonb,'["روماني (هيرودي)"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-63fe9eba7871','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','قلعة عسكرية عثمانية بناها السلطان سليمان لحماية برك المياه.','[]'::jsonb,'["\"قلاع فلسطين\" – د. النتشة"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-4b15f14c306f','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بنتها الإمبراطورة هيلانة فوق مغارة المهد سنة 326م، من أقدم الكنائس.','[{"title":"الموقع والتأسيس","draft_text":"تقع كنيسة المهد في قلب مدينة بيت لحم، على بُعد 10 كيلومترات جنوب القدس. بُنيت فوق مغارة طبيعية في صخر بيت لحم الكلسي، يُعتقد أنها شهدت ميلاد السيد المسيح. الكنيسة ليست مجرد موقع أثري، بل هي قلب الهوية المسيحية الفلسطينية وأقدس موقع مسيحي في العالم لا يزال قائماً منذ القرن الرابع الميلادي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"ما قبل الكنيسة: مغارة في حقل الرعاة","draft_text":"الموقع قبل بناء الكنيسة كان مغارة متواضعة في حقل الرعاة شرقي بيت لحم. الأناجيل تذكر أن مريم ويوسف جاءا من الناصرة إلى بيت لحم لاكتتاب السكان الذي أمر به الإمبراطور الروماني أغسطس، وهناك وُلد المسيح في مغارة لأن \"لم يكن لهما موضع في المنزل\". هذه القصة تجعل من بيت لحم، ومن هذه المغارة بالذات، نقطة ارتكاز للرواية المسيحية كلها. والرواية الفلسطينية المحلية تفتخر بأن الرعاة الذين بشروا بالميلاد هم رعاة فلسطينيون من حقول بيت لحم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البناء البيزنطي: هيلانة وقسطنطين","draft_text":"عام 326م، زارت القديسة هيلانة والدة الإمبراطور قسطنطين فلسطين، وأمرت ببناء كنيسة فوق المغارة. اكتمل البناء عام 339م. التصميم الأصلي كان بازيليكا ضخمة بفناء مكشوف وأروقة، وفوق المغارة مباشرة بُني مذبح. ما يميز هذه الكنيسة أن مدخلها كان واسعاً، لكنه ضُيق لاحقاً في العصور الوسطى إلى \"باب التواضع\" الحالي الذي لا يدخل منه الزائر إلا منحنياً. الرواية المحلية تقول إن هذا التضييق كان لمنع دخول الفرسان الصليبيين بخيولهم، لكن الأرجح أنه كان لمنع الفرسان المماليك من اقتحامها بخيولهم. على أي حال، \"باب التواضع\" أصبح رمزاً للخشوع والاحترام.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي: العهدة العمرية والحماية","draft_text":"بعد الفتح الإسلامي للقدس، حضر الخليفة عمر بن الخطاب إلى بيت لحم. الرواية الفلسطينية تروي أنه دخل الكنيسة وأدركته الصلاة، فصلى في الرواق الجنوبي، وليس في المذبح، احتراماً لقدسية المكان. ثم أعطى للبطريرك صفرونيوس عهداً كتابياً (العهدة العمرية لبيت لحم) يضمن فيه سلامة الكنيسة وأمن المسيحيين. هذا العهد جعل كنيسة المهد محمية إسلامياً طوال القرون. (مصدر: العهدة العمرية، محفوظة في مطرانية الروم الأرثوذكس – القدس).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الصليبيون والمماليك والعثمانيون","draft_text":"في العصر الصليبي، تُوّج فيها بلدوين الأول ملكاً على مملكة بيت المقدس (1100م). جددها المماليك وأضافوا بعض الزخارف. وفي العصر العثماني، حافظ السلاطين على الامتيازات والوضع الراهن. الكنيسة اليوم تحت رعاية ثلاث طوائف رئيسية: الروم الأرثوذكس، واللاتين الكاثوليك، والأرمن الأرثوذكس.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"كنيسة المهد والهوية الوطنية الفلسطينية","draft_text":"لا يمكن فصل كنيسة المهد عن النضال الفلسطيني. في عام 2002، أثناء الانتفاضة الثانية، حاصر الجيش الإسرائيلي مدينة بيت لحم، ولجأ 39 مقاتلاً فلسطينياً إلى الكنيسة طلباً للحماية. استمر الحصار 39 يوماً، وقُتل خلاله جرسون الكنيسة. هذا الحدث جعل من الكنيسة رمزاً وطنياً للمقاومة والصمود. اليوم، كنيسة المهد مُدرجة على قائمة التراث العالمي لليونسكو، والرئيس الفلسطيني محمود عباس هو من افتتح ترميمها الكبير عام 2018، مما يؤكد أنها تحت السيادة الفلسطينية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"كنيسة المهد هي شهادة ميلاد فلسطين المسيحية. هي المكان الذي بدأ فيه الإيمان المسيحي، ومنه انتشر إلى العالم. الرواية الفلسطينية تحرس هذا الإرث، مسلمين ومسيحيين معاً، ضد كل محاولات التهويد والطمس.\n\n(المصادر: \"تاريخ بيت لحم\" – الأب بطرس نجم، \"كنيسة المهد\" – مطرانية الروم الأرثوذكس، ملف اليونسكو لموقع الميلاد، أرشيف بلدية بيت لحم).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تاريخ بيت لحم\" – الأب بطرس نجم، اليونسكو (التراث العالمي)"]'::jsonb,'["روماني","بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-57adc62d6d70','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','كنيسة صغيرة قرب المهد، يُعتقد أن العذراء أرضعت يسوع هنا.','[]'::jsonb,'["\"دليل بيت لحم\" – بلدية بيت لحم"]'::jsonb,'["بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-e2a5c15f76f6','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مباني حجرية تقليدية، كنيسة القديس بطرس.','[{"title":"التسمية والتاريخ","draft_text":"بيرزيت بلدة قديمة تقع على تلة شمال رام الله. اسمها مشتق من \"بئر الزيت\"، مما يدل على شهرتها بزراعة الزيتون منذ القدم. في العصر الروماني والبيزنطي، كانت بيرزيت قرية زراعية مزدهرة تزود القدس بزيت الزيتون.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"كنيسة القديس بطرس","draft_text":"في قلب البلدة القديمة، تقف كنيسة القديس بطرس، وهي بناء حجري ضخم أشبه بقلعة. بُنيت في العصر البيزنطي، ودُمرت في الحروب الصليبية، ثم أعيد بناؤها في القرن 12. ما يميزها هو برج الجرس المحصن، الذي كان يستخدم للمراقبة والدفاع. الكنيسة اليوم تخدم الرعية المسيحية في بيرزيت، وهي دليل على عمق الوجود المسيحي في جبال رام الله.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة التقليدية","draft_text":"البلدة القديمة في بيرزيت محفوظة جيداً، ببيوتها الحجرية المقببة وأزقتها الضيقة. جامعة بيرزيت، التي بدأت كمدرسة صغيرة عام 1924 على يد المرحومة نبيهة ناصر، أصبحت اليوم إحدى أهم الجامعات الفلسطينية، مما جعل بيرزيت مركزاً فكرياً وثقافياً.\n\n(المصادر: \"تراث بيرزيت\" – جامعة بيرزيت، Riwaq).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تراث بيرزيت\" – جامعة بيرزيت"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-014e4c4e4845','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','موقع أثري به معاصر زيتون وكهوف. معاصر زيتون رومانية، كهوف، كنائس بيزنطية.','[{"title":"الموقع","draft_text":"تقع خربة عابود شمال غرب رام الله (أوردناها في مصفوفة الخليل لقربها من حدود المحافظة). هي موقع أثري غني يعود للعصرين الروماني والبيزنطي. ليست مجرد خربة، بل كانت بلدة مزدهرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"معاصر الزيتون","draft_text":"أهم ما في عابود هو معاصر الزيتون الرومانية المحفورة في الصخر. هذه المعاصر، بأحواضها وقنواتها، تثبت أن زراعة الزيتون كانت العمود الفقري لاقتصاد فلسطين منذ 2000 عام. لا تزال بعض هذه المعاصر تُستخدم حتى اليوم، مما يُظهر استمرارية مذهلة في التقاليد الزراعية الفلسطينية. الرواية المحلية تفتخر بأن زيت عابود كان يُصدر إلى روما.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الكنائس البيزنطية","draft_text":"في الموقع بقايا ثلاث كنائس بيزنطية بأرضيات فسيفسائية، مما يدل على أن عابود كانت مركزاً مسيحياً مهماً. إحدى هذه الكنائس ما زالت تستخدم للصلاة حتى اليوم، مما يجعلها واحدة من أقدم الكنائس المستخدمة باستمرار في العالم.\n\n(مصادر: SWP, Riwaq, \"الزيت والزيتون في فلسطين\" – د. شريف كناعنة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["مسح الآثار البريطاني (SWP)","هيئة الآثار الإسرائيلية، Riwaq"]'::jsonb,'["روماني","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-28dd528f5f3a','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','آثار دير قديم مع أرضيات فسيفساء.','[]'::jsonb,'["\"مسح رام الله\" – أريج"]'::jsonb,'["روماني","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-2a3fdab99250','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','خربة أثرية بجوار نبع ماء، تعود للعصر البرونزي.','[{"title":"الموقع","draft_text":"عين سامية هي نبع ماء دائم في وادي سامية، قرب قرية كفر مالك شرق رام الله. الموقع ليس مجرد نبع، بل هو خربة أثرية شاسعة تعود للعصر البرونزي الوسيط (حوالي 2000 ق.م).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المقبرة الملكية","draft_text":"في عين سامية، اكتُشفت مقبرة ملكية كنعانية تحتوي على أوانٍ فخارية راقية وأسلحة برونزية. هذا الاكتشاف يدل على أن المنطقة كانت مأهولة بقبائل كنعانية غنية ومنظمة. (مصدر: \"حفريات عين سامية\" – د. روبرت غرينبرغ، جامعة تل أبيب).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"مواقع العصر البرونزي\" – جامعة بيرزيت"]'::jsonb,'["كنعاني","روماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
