insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-12fc185d4b0b','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام تاريخي، تقام حوله مواسم شعبية.','[]'::jsonb,'["\"الموسم النبوي\" – كناعنة"]'::jsonb,'["أيوبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a9ac192e20c3','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','تحتوي على أزقة وأسواق (خان التجار)، مساجد أثرية (النصر، الخضر)، وحمامات تركية.','[{"title":"الجغرافيا والتسمية","draft_text":"تقع نابلس في وادٍ خصب بين جبلي عيبال شمالاً وجرزيم جنوباً. موقعها لم يتغير منذ آلاف السنين؛ فهي تقوم على أنقاض مدينة \"شكيم\" الكنعانية، التي كانت أهم مدينة-دولة في شمال فلسطين في الألف الثاني قبل الميلاد. اسمها الحالي \"نابلس\" مشتق من الاسم الروماني \"نيابوليس\" (المدينة الجديدة) الذي أطلقه الإمبراطور فسبسيان عام 72م بعد تدميره لشكيم القديمة. هذا التراكم في الأسماء – شكيم الكنعانية، نيابوليس الرومانية، نابلس العربية – يختزل تاريخ فلسطين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الكنعاني: شكيم المدينة العاصية","draft_text":"شكيم كانت مدينة-دولة كنعانية قوية. في رسائل تل العمارنة (القرن 14 ق.م)، يشتكي ملكها \"لبايا\" من هجمات البدو (العبيرو) ويتآمر مع ملوك آخرين ضد السلطة المصرية. هذه الرسائل، المحفوظة في المتحف المصري، تظهر أن المدن الكنعانية كانت دولاً ذات سيادة تتفاوض وتتمرد وتتحالف. الرواية الفلسطينية ترى في لبايا جداً للزعماء الوطنيين، أول مقاوم للهيمنة الإمبراطورية في فلسطين. (مصدر: رسائل تل العمارنة – ترجمة د. أحمد فخري).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الروماني: نيابوليس الوثنية","draft_text":"دمر الرومان شكيم القديمة وأعادوا بناءها على الطراز الروماني الكلاسيكي. بنوا فيها مسرحاً، ومدرجاً، ومعابد (أشهرها معبد زيوس على جبل جرزيم). العملة النابلسية الرومانية تحمل صورة الإمبراطور ومعبد الجبل، مما يدل على أهميتها. الرواية المحلية تذكر أن المسرح الروماني ما زالت بقاياه تحت أحياء نابلس الحديثة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي: نابلس العربية","draft_text":"بعد الفتح الإسلامي، أصبحت نابلس مدينة إسلامية عربية. جامع النصر (حوّل من كنيسة صليبية)، وجامع الخضراء، هما من أقدم مساجدها. لكن هوية نابلس الحقيقية تشكلت في العصرين المملوكي والعثماني، حين أصبحت مركزاً تجارياً هائلاً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"نابلس العثمانية: مركز التجارة والصابون","draft_text":"في العصر العثماني (القرن 16-20)، كانت نابلس أغنى مدينة في فلسطين بعد القدس، وربما قبلها. اشتهرت بصناعة الصابون النابلسي المصنوع من زيت الزيتون، وصناعة النسيج، ودباغة الجلود. خاناتها (خان التجار، خان الوكالة) كانت تعج بقوافل الحج والتجارة بين دمشق والقاهرة والحجاز. سجلات المحكمة الشرعية في نابلس تُظهر مجتمعاً تجارياً متقدماً، فيه شركات عائلية، وعقود مضاربة، وتأمين على القوافل. عائلات نابلسية مثل آل عبد الهادي وآل طوقان وآل النمر تحولت إلى قوى سياسية واقتصادية حكمت مناطق واسعة من فلسطين. (مصدر: \"نابلس في العهد العثماني\" – د. بشارة دوماني، سجلات محكمة نابلس الشرعية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"البلدة القديمة اليوم","draft_text":"البلدة القديمة في نابلس هي واحدة من أفضل البلدات القديمة المحفوظة في فلسطين، رغم الدمار الذي لحق بها أثناء الاجتياح الإسرائيلي عام 2002. أزقتها الضيقة، وأسواقها المسقوفة، وحماماتها التركية (حمام الشفاء، حمام السمرة)، وكنائسها ومساجدها، ومصابنها (مصابن الصابون) ما زالت تعمل. الرواية الفلسطينية الحية هنا هي رواية إعادة الإعمار؛ فبعد دمار 2002، أعاد النابلسيون بناء أسواقهم وبيوتهم حجراً حجراً.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"نابلس هي القلب التجاري والاقتصادي لفلسطين عبر العصور. من شكيم المتمردة على فرعون، إلى نيابوليس الرومانية، إلى نابلس العثمانية عاصمة الصابون والتجارة، إلى البلدة القديمة التي تنهض من تحت الركام اليوم، نابلس هي قصة صمود وازدهار لا ينقطع.\n\n(المصادر: \"نابلس: تاريخ وتراث\" – جامعة النجاح الوطنية، Riwaq، سجلات محكمة نابلس الشرعية، \"الصابون النابلسي\" – وزارة الثقافة الفلسطينية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"نابلس التاريخية\" – جامعة النجاح، Riwaq"]'::jsonb,'["روماني","بيزنطي","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a429c345ac25','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','من أقدم مساجد نابلس، حول من كنيسة صليبية.','[]'::jsonb,'["\"مساجد فلسطين\" – د. رائف يوسف"]'::jsonb,'["أيوبي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-b6773e683274','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','موقع مقدس للسامريين، به آثار معبد زيوس الروماني.','[{"title":"الموقع وقدسية المكان","draft_text":"جبل جرزيم هو الجبل الجنوبي المطل على نابلس (ارتفاع 881م). بالنسبة للطائفة السامرية، هو أقدس مكان على وجه الأرض، وهو قبلتهم وقبلتهم الحقيقية، وليس القدس. السامريون يؤمنون أن إبراهيم همّ بذبح ابنه إسحق على هذا الجبل (لا على جبل الموريا في القدس كما تؤمن التوراة اليهودية)، وأن يشوع بن نون بنى مذبح بني إسرائيل عليه بعد دخول أرض كنعان، وأن الهيكل الحقيقي كان عليه وليس في القدس.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"السامريون: الشعب المضطهد","draft_text":"السامريون هم أقدم طائفة دينية مستمرة في فلسطين. يزعمون أنهم بقية بني إسرائيل الحقيقيين الذين لم يسبهم الآشوريون عام 722 ق.م، بل بقوا في أرضهم. اليهود يعتبرونهم هراطقة. عددهم اليوم لا يتجاوز 800 شخص، يعيش نصفهم في حارة السامريين على جبل جرزيم في نابلس، ونصفهم الآخر في حولون قرب تل أبيب. الرواية الفلسطينية ترى فيهم أقلية وطنية فلسطينية أصلية، وجزءاً من النسيج الوطني. هم الوحيدون الذين يحملون الجنسيتين الفلسطينية والإسرائيلية، ويتحدثون العربية والعبرية، ويحافظون على لغتهم السامرية القديمة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الآثار على الجبل","draft_text":"على قمة جرزيم، بقايا معبد سامري قديم دمره المكابيون اليهود في القرن الثاني ق.م، وهو أكبر جرح في الذاكرة السامرية. هناك أيضاً بقايا كنيسة بيزنطية بُنيت فوق المعبد المهدم، وقلعة صغيرة من العصر الأيوبي. في كل عام، يقيم السامريون ذبيحة الفصح على الجبل، وهو احتفال مهيب يجذب الزوار من العالم. الرواية الفلسطينية المحلية تعتبر هذا الاحتفال جزءاً من تراث نابلس. (مصدر: \"السامريون: تاريخ وعقيدة\" – د. حسني دعيس، مقابلات مع كهنة الطائفة السامرية – أرشيف جامعة النجاح).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"السامريون في نابلس\" – د. حسني دعيس"]'::jsonb,'["سامري","روماني","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
