insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-31c7667ff10e','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','خان كبير في قلب المدينة، كان مركزاً تجارياً.','[]'::jsonb,'["\"الخانات الفلسطينية\" – وزارة السياحة"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-6f6afe87f969','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','عاصمة مملكة السامرة، بها آثار رومانية (مسرح، كنيسة). آثار رومانية (مسرح، بازيليك).','[{"title":"الجغرافيا والتسمية","draft_text":"تقع سبسطية على تل استراتيجي يطل على سهل خصب، شمال غرب نابلس. اسمها الكنعاني الأصلي \"شمرون\" (أو سامر)، ويعني \"مكان الحراسة\" أو \"البرج\"، مما يعكس وظيفتها الدفاعية منذ البداية. التل محاط بوديان عميقة من ثلاث جهات، مما جعله حصناً طبيعياً. الاسم الحالي \"سبسطية\" هو تحريف للاسم اليوناني \"سيباستي\" الذي أطلقه هيرودس الكبير (القرن الأول ق.م) تكريماً للإمبراطور الروماني أغسطس (سيباستوس باليونانية). هذه الطبقات اللغوية (كنعاني، يوناني، عربي) تختزل تاريخ الموقع وتؤكد أصالته الفلسطينية المتصلة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الكنعاني والإسرائيلي: البدايات","draft_text":"كانت شمرون مدينة-دولة كنعانية في الألف الثاني ق.م. ذكرت في نصوص اللعنات المصرية (القرن 18 ق.م) وفي رسائل تل العمارنة. اشترى الملك عمري (القرن التاسع ق.م) التل من رجل كنعاني اسمه \"شامر\" بمبلغ من الفضة، كما تروي الرواية التوراتية نفسها (سفر الملوك الأول 16:24). وهنا تظهر الرواية المضادة: حتى مملكة السامرة الإسرائيلية لم تنشأ على أرض خالية، بل بُنيت على مدينة كنعانية موجودة، واشترى مؤسسوها الأرض. هذا يؤكد أن الوجود العربي الكنعاني هو الأصل، وما جاء بعده كان طبقة فوقه.\n\nجعلها الملك عمري عاصمته، ووسعها ابنه آخاب الذي بنى \"معبد البعل\" و\"القصر العاجي\". كشفت الحفريات عن مئات القطع العاجية المنحوتة بفخامة، مما يؤكد ثراء المدينة. دمرها الآشوريون عام 722 ق.م وسبوا سكانها. هنا تتبنى الرواية الفلسطينية حقيقة أن \"الأسباط العشرة المفقودة\" لم تكن إلا نخبة حاكمة، أما الفلاحين الكنعانيين (السامريين) فقد بقوا في أرضهم واستمروا يزرعونها. وهذا ما يفسر استمرار الوجود السامري في نابلس حتى اليوم، وهم جزء من النسيج الفلسطيني.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الروماني: إعادة التأسيس الهيرودية","draft_text":"في عام 27 ق.م، منح الإمبراطور أغسطس المدينة لهيرودس الكبير. أعاد هيرودس، المعروف بمشاريعه العمرانية الضخمة، بناءها بالكامل على الطراز الروماني. شيّد:\n\nمعبداً ضخماً للإمبراطور أغسطس على قمة التل (بقاياه ما زالت ظاهرة).\n\nمسرحاً رومانياً يتسع لـ 3000 متفرج، منحوت في سفح التل.\n\nملعباً (استاداً) للألعاب الرياضية.\n\nشوارع مرصوفة بالأعمدة (الكاردو والديكومانوس).\n\nهذا المزيج من المعبد والمسرح هو ما يجعل سبسطية فريدة. الرواية المحلية تسمي المسرح \"المدرج\"، وكان أهالي سبسطية، قبل الاحتلال، يقيمون فيه حفلاتهم وأعراسهم. هذا الاستخدام الشعبي المعاصر للمكان الأثري هو جزء من الرواية الفلسطينية الحية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر البيزنطي: التحول للمسيحية","draft_text":"مع اعتناق الإمبراطورية المسيحية، تحولت سبسطية إلى مركز أسقفي مهم. تحطم المعبد الروماني وحلّت محله كنيسة بازيليكية. يُعتقد أن رفات القديس يوحنا المعمدان نُقلت إلى هنا، مما جعلها محجة للحجاج. لا تزال بقايا الكنيسة البيزنطية ظاهرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي: الاستمرارية","draft_text":"بعد الفتح الإسلامي، لم تُهجر سبسطية. استمرت كقرية عامرة، وسكنتها قبائل عربية. تعايش المسلمون مع السامريين والمسيحيين فيها. الرواية الشفوية تذكر أن مسجد القرية القديم بُني بجوار الكنيسة البيزنطية دون هدمها.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الصليبي: الكاتدرائية والجامع","draft_text":"في القرن 12، أقام الصليبيون كاتدرائية ضخمة على أنقاض الكنيسة البيزنطية، مكرسة للقديس يوحنا المعمدان. بعد تحرير صلاح الدين للمنطقة، لم تُهدم الكاتدرائية، بل حُوّل جزء منها إلى الجامع الكبير في سبسطية، وظل جزء آخر مقاماً للنبي يحيى (يوحنا المعمدان) يزوره المسلمون والمسيحيون على السواء. هذا التحول السلمي من كنيسة إلى جامع ومقام مشترك هو نموذج نادر للتعايش، تؤكده الرواية الفلسطينية وتفخر به. (مصدر: \"الآثار الصليبية في فلسطين\" – د. يوسف النتشة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الحديث: الإهمال والتهديد","draft_text":"تقع سبسطية اليوم في المنطقة (ج) الخاضعة للسيطرة الإسرائيلية الكاملة. الرواية الفلسطينية المعاصرة هي رواية معاناة: الموقع الأثري المهمل الذي ينهار، منع الحفائر الفلسطينية فيه، تحويل المنطقة المحيطة إلى مستوطنات، وإغلاق الطرق. كما يروي الباحث د. أسامة حمدان: \"سبسطية متحف مفتوح يضيع أمام أعيننا\".","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"سبسطية هي فلسطين مصغّرة: كنعانية الأصل، توجها الرومان، احتضنت المسيحية والإسلام، تعايشت فيها الأديان، وتواجه اليوم خطر الطمس. إنقاذ روايتها هو إنقاذ لذاكرة المكان.\n\n(المصادر: كتاب \"سبسطية عبر التاريخ\" – معهد أريج، \"تاريخ فلسطين القديم\" – خالد عوض، سجلات SWP، شهادات سكان سبسطية – أرشيف مركز المعمار الشعبي رواق).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"سبسطية عبر التاريخ\" – أريج، \"دليل الآثار الرومانية\"","\"سبسطية\" – أريج"]'::jsonb,'["كنعاني","إسرائيلي","روماني","صليبي","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-d00341226494','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام تاريخي.','[]'::jsonb,'["\"موسوعة المقامات\""]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-fb9a817ec94a','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مقام منسوب ليوسف عليه السلام، في منطقة سبسطية. مقام منسوب للنبي يوسف، تعرض لتدمير وإعادة بناء.','[{"title":"الموقع والرواية","draft_text":"يقع مقام النبي يوسف في بلدة بلاطة، على المدخل الشرقي لمدينة نابلس. هو بناء حجري أبيض صغير بقبة خضراء. الرواية الإسلامية تؤكد أن النبي يوسف بن يعقوب دُفن هنا. بينما تذكر التوراة أن عظامه نُقلت من مصر إلى شكيم (بلاطة الحالية) ودُفنت في \"قطعة الحقل التي اشتراها يعقوب\". هذا التطابق النادر بين الروايتين الإسلامية والتوراتية يجعل الموقع ذا أهمية استثنائية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"التاريخ الإسلامي","draft_text":"ظل المقام مزاراً إسلامياً طوال القرون. جُدد في العصر الفاطمي، ثم المملوكي، ثم العثماني. كان جزءاً من الوقف الإسلامي في نابلس، وتقام عنده الصلوات والموالد.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النزاع الحديث","draft_text":"بعد اتفاقية أوسلو (1995)، وقع المقام في المنطقة (ب) الخاضعة للسيطرة المدنية الفلسطينية والأمنية الإسرائيلية المشتركة. في عام 2000، مع بدء الانتفاضة الثانية، سيطر الفلسطينيون على المقام لفترة قصيرة، ثم استعادته إسرائيل بالقوة. منذ ذلك الحين، وهو موقع عسكري إسرائيلي مغلق، ويمنع المسلمون من الصلاة فيه إلا بتصاريح خاصة ومرافقة عسكرية، وعادة في ساعات الليل فقط. الرواية الفلسطينية ترى في هذا الإغلاق استمراراً لتهويد الأماكن المقدسة. في عام 2015، أحرق فلسطينيون أجزاء من المقام احتجاجاً، مما أثار موجة إدانة وإعادة ترميم إسرائيلية. اليوم، المقام رمز للصراع على المقدسات في فلسطين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"مقام النبي يوسف هو نبي يجمع ولا يفرق. لكن الاحتلال جعله ثكنة عسكرية وسجن للمقدسات. الرواية الفلسطينية تطالب بإعادته إلى الوقف الإسلامي وفتحه للمصلين بحرية.\n\n(المصادر: \"مقامات فلسطين\" – وزارة الأوقاف، \"النزاع على المقدسات\" – مركز القدس للحقوق، شهادات أهالي بلاطة – أرشيف جامعة النجاح).\n\nبهذا أكملت أبرز مواقع محافظة نابلس. سأنتقل إلى محافظة جنين فأقدم رواياتها الموسعة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"مقامات الأنبياء\" – د. أحمد حجازي","\"مقامات فلسطين\" – وزارة الأوقاف"]'::jsonb,'["فاطمي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-f2a7fbbda5a5','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','حارات وأسواق قديمة، قصر الكايد.','[]'::jsonb,'["\"تاريخ جنين\" – د. نمر سرحان"]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-0ae63f2b6a17','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','آثار مدينة كنعانية.','[]'::jsonb,'["\"حفريات جنين\" – دائرة الآثار"]'::jsonb,'["برونزي","كنعاني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-fe1e2a1605b5','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','قصر أثري لعائلة عبد الهادي.','[{"title":"الموقع والتسمية","draft_text":"جنين مدينة قديمة في أقصى شمال الضفة الغربية، تطل على مرج ابن عامر (سهل زرعين) الخصب. اسمها مشتق من \"عين جنيم\" الكنعانية (عين الجنائن)، مما يعكس خصوبة الموقع وغزارة مياهه. هي بوابة فلسطين الشمالية، والرابط بين جبال نابلس وسهل مرج ابن عامر وجبال الكرمل.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الكنعاني والروماني","draft_text":"قامت جنين على أنقاض مدينة \"عين جنيم\" الكنعانية. في العصر الروماني، كانت قرية صغيرة تابعة لمدينة سبسطية. لكن أهميتها نمت تدريجياً بسبب موقعها على طريق القوافل بين مصر ودمشق.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي: جنين العربية","draft_text":"بعد الفتح الإسلامي، استقرت قبائل عربية في المنطقة. في العصر المملوكي، أصبحت جنين محطة على طريق البريد بين دمشق والقاهرة. بنى المماليك فيها قلعة صغيرة لحماية الطريق. في العصر العثماني، أصبحت مركز ناحية (قضاء) يتبع لواء اللجون. سجلات المحكمة الشرعية في نابلس (التي كانت تتبع لها جنين) تذكر جنين كمركز زراعي ينتج القمح والشعير والسمسم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"قصر الكايد: حصن آل عبد الهادي","draft_text":"في القرن 18-19، حكمت عائلة عبد الهادي النابلسية منطقة جنين. بنوا \"قصر الكايد\" في قلب جنين، وهو قلعة صغيرة بأسوار عالية وأبراج للمراقبة. القصر كان مركزاً للإدارة وجباية الضرائب. الرواية المحلية تروي قصصاً عن صراعات آل عبد الهادي مع آل طوقان في نابلس، وعن تحالفهم مع ظاهر العمر حاكم عكا. القصر اليوم مهجور جزئياً لكنه ما زال قائماً. (مصدر: \"العائلات الإقطاعية في فلسطين\" – د. بشارة دوماني، Riwaq).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"جنين الحديثة: المخيم والمقاومة","draft_text":"بعد نكبة 1948، أُقيم مخيم جنين للاجئين غرب المدينة، وسكنه لاجئون من حيفا والكرمل. تحول المخيم إلى معقل للمقاومة الفلسطينية. في اجتياح 2002 (عملية السور الواقي)، تعرض المخيم لدمار هائل في معركة استمرت عشرة أيام، استشهد فيها 52 فلسطينياً و23 جندياً إسرائيلياً. هذه المعركة جعلت من جنين رمزاً للمقاومة والصمود في الوجدان الفلسطيني. الرواية الحية لجنين اليوم هي رواية إعادة البناء والتحدي.\n\n(المصادر: \"جنين: تاريخ وحضارة\" – د. نمر سرحان، \"مخيم جنين: ذاكرة ومقاومة\" – مركز بديل، شهادات الناجين من معركة 2002).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["Riwaq"]'::jsonb,'["عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-2c1f6b6dbd51','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','كنيسة القديس جاورجيوس، من أقدم كنائس العالم، بُنيت في القرن الرابع.','[{"title":"الموقع والتأسيس","draft_text":"تقع كنيسة القديس جاورجيوس (الخضر) في بلدة برقين، غرب جنين. تُعرف ببساطة باسم \"كنيسة برقين\". الرواية الكنسية الفلسطينية تؤكد أنها خامس أقدم كنيسة في العالم، ورابع أقدس موقع مسيحي بعد القدس وبيت لحم والناصرة. بُنيت في القرن الرابع أو الخامس الميلادي، وما زالت تستخدم للصلاة حتى اليوم، مما يجعلها واحدة من أقدم الكنائس المستخدمة باستمرار في العالم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"معجزة المسيح","draft_text":"بحسب التقليد المسيحي، مرّ المسيح بقرية برقين في طريقه من الناصرة إلى القدس، وشفى فيها عشرة برص كانوا منعزلين في مغارة خارج القرية. هذه المغارة ما زالت موجودة داخل الكنيسة، وتحولت إلى مزار مقدس. قصة الشفاء هذه (المذكورة في إنجيل لوقا 17:11-19) تجعل من برقين محطة في طريق الآلام، وتضفي على الكنيسة قدسية خاصة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة والترميم","draft_text":"الكنيسة مبنية بالحجر الكلسي الأبيض، بتصميم بازيليكي بسيط. جُددت عدة مرات عبر العصور، آخرها ترميم كبير قامت به وزارة السياحة الفلسطينية وبلدية برقين بتمويل دولي. الكنيسة اليوم تخدم الرعية المسيحية الصغيرة في برقين، وتستقبل الحجاج من كل العالم.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"خلاصة الرواية","draft_text":"كنيسة برقين هي الدليل الحي على أن جذور المسيحية في شمال فلسطين عميقة ومستمرة. إنها تثبت أن فلسطين ليست مجرد أرض الأنبياء، بل هي أيضاً أرض المعجزات والقديسين.\n\n(المصادر: \"دليل كنائس فلسطين\" – مطرانية الروم الأرثوذكس، بلدية برقين، \"طريق الآلام في فلسطين\" – وزارة السياحة).\n\nبهذا أكملت محافظة جنين. سأنتقل إلى محافظة رام الله والبيرة، ثم أواصل بلا توقف حتى نهاية محافظات غزة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"دليل كنائس فلسطين\" – مطرانية الروم الأرثوذكس"]'::jsonb,'["بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-fc3cde18193c','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام تاريخي في المدينة.','[]'::jsonb,'["\"المقامات\" – أريج"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a28891855f38','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','أزقة قديمة ومساجد أثرية.','[]'::jsonb,'["\"تاريخ طولكرم\" – بلدية طولكرم"]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-7a4bd929848c','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','برج أثري وبقايا قلعة صغيرة.','[{"title":"سياق محافظة طولكرم","draft_text":"تقع مدينة طولكرم في السهل الساحلي الفلسطيني، على الحافة الغربية لجبال نابلس، حيث يلتقي السهل بالجبل. اسمها مشتق من \"طور الكرم\" (جبل الكرم)، مما يدل على شهرتها بزراعة الكروم والزيتون منذ القدم. هي بوابة فلسطين على البحر المتوسط، وهمزة الوصل بين الساحل والداخل.\n\nقامت طولكرم على أنقاض بلدة \"بيرات سورقا\" الرومانية (بئر الكروم). كانت محطة على الطريق الروماني بين قيسارية ماريتيما (عاصمة فلسطين الرومانية) ونابلس. في العصر البيزنطي، أصبحت مركزاً زراعياً يزود الساحل بالغلال. بقايا معاصر الزيتون الرومانية المنتشرة حول المدينة تشهد على هذا التاريخ الزراعي العميق.\n\nبعد الفتح الإسلامي، استقرت قبائل عربية في المنطقة، وتحول الاسم إلى \"طور الكرم\". في العصر المملوكي، أصبحت طولكرم مركز ناحية إدارية. لكن ازدهارها الحقيقي كان في العصر العثماني، حين أصبحت مركزاً لتجارة الحبوب والزيت بين جبال نابلس وموانئ يافا وحيفا. سجلات المحكمة الشرعية في نابلس تذكر تجاراً من طولكرم كانوا يصدرون زيت الزيتون إلى مصر وفرنسا. (مصدر: \"طولكرم: تاريخ وتراث\" – بلدية طولكرم).\n\nفي الانتداب البريطاني، أقام البريطانيون معسكراً كبيراً في طولكرم (معسكر نور الشام)، تحول بعد النكبة إلى مخيم للاجئين (مخيم طولكرم). المدينة اليوم هي مركز محافظة طولكرم، وتعاني من جدار الفصل العنصري الذي يعزلها عن أراضيها الزراعية في السهل الساحلي. الرواية الفلسطينية المعاصرة هنا هي رواية فلاحين فصلوا عن أرضهم بجدار إسمنتي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الموقع والبناء","draft_text":"تقع خربة برج العبد على تلة مشرفة قرب بلدة عنبتا، شرق طولكرم. هي بقايا برج حجري ضخم وقلعة صغيرة، بُنيت في العصر الصليبي (القرن 12) كجزء من سلسلة حصون كانت تحمي طريق القوافل بين الساحل ونابلس. البرج مبني بالحجر الكلسي المشذب، وله أساسات ضخمة ما زالت ظاهرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الوظيفة العسكرية والتجارية","draft_text":"لم يكن البرج مجرد نقطة عسكرية، بل كان أيضاً محطة جباية للضرائب (رسوم المرور) على القوافل التجارية. في العصر المملوكي، جُدد البرج وأُضيفت إليه تحصينات. الرواية المحلية تسميه \"برج العبد\" نسبة إلى أمير مملوكي أو جندي مجهول. البرج اليوم مهمل، لكنه يظل شاهداً على أهمية المنطقة كمعبر استراتيجي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الرواية الشفوية","draft_text":"أهالي عنبتا يروون أن البرج كان يستخدم في العصر العثماني كمركز للمراقبة ضد غارات البدو، وفيه بئر ماء عميقة كان يلجأ إليها السكان أثناء الهجمات. هذه الرواية الشفوية تدمج بين التاريخ العسكري والذاكرة الشعبية. (مصدر: \"قلاع شمال فلسطين\" – معهد أريج).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"قلاع الشمال\" – أريج"]'::jsonb,'["صليبي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-0c0a379f20f7','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','خربة تضم معاصر وكهوف.','[{"title":"الموقع","draft_text":"تقع خربة جبع على تلة قرب بلدة جبع، جنوب طولكرم. هي موقع أثري واسع يضم بقايا بلدة رومانية-بيزنطية كاملة، لكن أهم ما فيها هو معاصر الزيتون المنحوتة في الصخر، وكهوف الدفن.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المعاصر والاقتصاد القديم","draft_text":"معاصر جبع هي من أكبر المعاصر الرومانية في شمال فلسطين. أحواضها الحجرية الضخمة وقنواتها المتقنة تدل على إنتاج زيت زيتون بكميات تجارية ضخمة. الزيت كان يُصدر إلى روما والقسطنطينية. الرواية الفلسطينية ترى في هذه المعاصر دليلاً على أن زراعة الزيتون كانت ولا تزال العمود الفقري لاقتصاد فلسطين، وأن الفلاح الفلسطيني هو وريث هذه الحضارة الزراعية مباشرة. (مصدر: SWP, \"الزيت والزيتون في فلسطين\" – د. شريف كناعنة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الكهوف والدفن","draft_text":"في جبع أيضاً مدافن وكهوف مسكونة في الذاكرة الشعبية. الرواية المحلية تروي قصصاً عن \"الغولة\" و\"الكنز\" المخبأ في هذه الكهوف، مما يعكس تداخل التاريخ الأثري مع الخيال الشعبي الفلسطيني.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["SWP"]'::jsonb,'["روماني","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-be1c2ce90997','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','تقدم المسودة طولكرم كمدينة على صلة بالسهل الساحلي وطرق التجارة والزراعة والتحولات الحديثة، وتحتاج روايتها إلى مصادر محلية وخرائط تاريخية.','[]'::jsonb,'["\"تاريخ طولكرم\" – بلدية طولكرم، وإحالات الرواية الموسعة"]'::jsonb,'["روماني","إسلامي","عثماني","حديث"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
