insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-02cb039fe1eb','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','خربة تضم بقايا كنيسة بيزنطية.','[]'::jsonb,'["SWP"]'::jsonb,'["بيزنطي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-3ab4c5b64173','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','آثار رومانية تحت البلدة.','[{"title":"الموقع والتسمية","draft_text":"تقع قلقيلية في أقصى غرب الضفة الغربية، ملاصقة للخط الأخضر. اسمها مشتق من \"قالي قلا\" الكنعانية (حصن الحجارة)، مما يدل على قدمها. كانت قرية زراعية صغيرة حتى أوائل القرن العشرين، لكنها نمت بسرعة بعد النكبة لتصبح مدينة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الروماني والإسلامي","draft_text":"قامت قلقيلية على أنقاض بلدة رومانية صغيرة. في العصر المملوكي، كانت محطة على طريق الحج الشامي. لكن زلزال 1927 دمر معظم مبانيها القديمة، فلم يبقَ من تراثها المعماري الكثير.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الجدار والتحول إلى سجن","draft_text":"الرواية الفلسطينية الحديثة لقلقيلية هي رواية مأساوية. بعد عام 2002، أحاطت إسرائيل المدينة بجدار الفصل العنصري من ثلاث جهات، تاركة منفذاً واحداً يسيطر عليه حاجز عسكري. قلقيلية تحولت إلى سجن كبير، وعُزلت عن أراضيها الزراعية وعن محيطها الفلسطيني. هذه الرواية الحية تطغى على كل تاريخها القديم، وتجعل من قلقيلية رمزاً لمعاناة المدن الفلسطينية المحاصرة. (مصدر: تقارير \"أوقفوا الجدار\" – مؤسسة الحق، بلدية قلقيلية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"آثار قلقيلية\" – بلدية قلقيلية"]'::jsonb,'["روماني","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a33c0a4f64fa','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مقام تاريخي مشهور.','[{"title":"الموقع والرواية","draft_text":"يقع مقام النبي يامين على تلة قرب بلدة عزون، شرق قلقيلية. هو بناء حجري أبيض بقبة، منسوب لبنيامين (ابن يعقوب)، أحد الأسباط. الرواية المحلية تؤكد أن بنيامين دُفن هنا. بينما لا يوجد دليل أثري قاطع، فإن المقام كان مزاراً إسلامياً مهماً لقرون.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الممارسات الشعبية","draft_text":"كان أهالي عزون والقرى المجاورة يزورون المقام في المواسم، ويقيمون عنده الذبائح والنذور، خاصة لطلب الشفاء من الأمراض. النساء كن يربطن أقمشة خضراء على شبابيك المقام للتبرك. هذه الممارسات، التي تراجع كثيراً في العقود الأخيرة، هي جزء من التراث الديني الشعبي الفلسطيني الذي يدمج بين التصوف والإيمان الشعبي. (مصدر: \"مقامات شمال فلسطين\" – أريج، شهادات شفوية من أهالي عزون).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"المقامات\" – أريج"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-69f3ad775733','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بقايا دير روماني، معاصر، ومسجد أثري.','[{"title":"الموقع والتسمية","draft_text":"تقع دير استيا على تلة في جبال سلفيت. اسمها يحمل قصتها: \"دير\" إشارة إلى دير مسيحي بيزنطي، و\"استيا\" تحريف لاسم القديسة إستير أو أستيا. أي أن القرية قامت على أنقاض دير بيزنطي.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الدير البيزنطي والتحول الإسلامي","draft_text":"بقايا الدير البيزنطي (أرضيات فسيفساء، معاصر، آبار) ما زالت ظاهرة في القرية. بعد الفتح الإسلامي، تحول الدير تدريجياً إلى قرية زراعية. لكن الأهم أن مسجد القرية الحالي بُني فوق موقع الدير القديم، في استمرارية للمكان المقدس. هذا التحول السلمي من دير إلى مسجد وقرية هو نموذج مصغر لتاريخ فلسطين. (مصدر: SWP, Riwaq).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"عيون الماء والقنوات الرومانية","draft_text":"في محيط دير استيا، توجد عيون ماء دائمة وقنوات رومانية مدهشة. \"عين المزراب\" هي نبع يخرج من نفق صخري، وتجري مياهه في قناة حجرية مكشوفة. هذه القنوات، التي ما زالت تروي البساتين حتى اليوم، هي استمرارية حية للهندسة الرومانية. (مصدر: \"أنظمة المياه في فلسطين\" – م. ناصر الدين).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["SWP، Riwaq"]'::jsonb,'["روماني","بيزنطي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-ba91049d51a9','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','قنوات رومانية وآبار أثرية.','[]'::jsonb,'["\"أنظمة المياه\" – م. ناصر الدين"]'::jsonb,'["روماني","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-b2a7e03ecda1','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بقايا قلعة صليبية.','[{"title":"الموقع","draft_text":"تقع كفل حارس على جبل مرتفع شمال سلفيت. هي بلدة قديمة تضم مقاماً إسلامياً يُعرف بمقام \"ذو الكفل\" (النبي حزقيال)، وقلعة صليبية مهدمة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"المقام والقلعة","draft_text":"المقام هو بناء عثماني متواضع فوق مغارة. الرواية المحلية تؤكد أن ذا الكفل دُفن هنا. بجانب المقام، بقايا قلعة صليبية بناها فرسان الهيكل لحماية الطريق بين القدس وعكا. بعد تحرير صلاح الدين، هُدمت القلعة وبقي المقام. هذا التجاور بين القلعة المهدمة والمقام القائم يرمز لانتصار القداسة على العسكرة. (مصدر: \"مقامات فلسطين\" – وزارة الأوقاف، \"قلاع فلسطين\" – د. يوسف النتشة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"قلاع فلسطين\" – د. النتشة"]'::jsonb,'["صليبي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-c6731a990917','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','مستوطنة كنعانية هامة.','[{"title":"الموقع والاكتشاف","draft_text":"يقع تل الفارعة على بُعد 12 كم شمال شرق نابلس، قرب عين الفارعة. هو تل أثري ضخم يحوي بقايا مدينة كنعانية محصنة من العصر البرونزي (حوالي 3000-1200 ق.م). اكتشفته البعثة الفرنسية بقيادة الأب رولان دوفو بين 1946-1960، وأظهرت الحفريات أنها كانت من أكبر المدن الكنعانية في شمال فلسطين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة والتحصينات","draft_text":"أهم ما كُشف في تل الفارعة هو بوابة المدينة الكنعانية الضخمة، والسور الحجري، والمعبد الكنعاني، والبيوت السكنية المنظمة. التخطيط العمراني المتقدم يدل على مجتمع حضري منظم. الرواية الفلسطينية ترى في هذه المدينة دليلاً على أن فلسطين كانت أرض حضارة ومدنية قبل آلاف السنين من وصول العبرانيين. (مصدر: \"حفريات تل الفارعة\" – جامعة النجاح، تقارير البعثة الفرنسية).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الحديدي والإسلامي","draft_text":"بعد دمار المدينة الكنعانية، سكن الموقع في العصر الحديدي (الإسرائيلي)، ثم في العصر الروماني والبيزنطي. في العصر الإسلامي، تحول إلى قرية زراعية صغيرة. اليوم، الموقع مهمل ويعاني من الحفريات غير الشرعية، لكنه يظل أحد أهم المواقع الأثرية في فلسطين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"حفريات الفارعة\" – جامعة النجاح"]'::jsonb,'["برونزي","كنعاني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-4ab7d2100cc2','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','أرضيات فسيفساء وآبار.','[]'::jsonb,'["SWP"]'::jsonb,'["روماني","بيزنطي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-bc56c2f93d66','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','نبع مائي قديم عليه قناطر.','[{"title":"الموقع","draft_text":"عين الفارعة هي نبع ماء دائم وغزير في وادي الفارعة، شرق طوباس. هي واحدة من أكبر الينابيع في فلسطين، وتصب في نهر الأردن. حولها واحة خضراء من البساتين.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الطواحين العثمانية","draft_text":"على ضفاف قناة العين، بنى العثمانيون سلسلة طواحين مائية (حوالي 12 طاحونة) لطحن القمح. هذه الطواحين، بآبارها وعقودها الحجرية، ما زالت بقاياها ظاهرة. كانت تخدم قرى شمال نابلس وطوباس. الرواية المحلية تروي أن الفلاحين كانوا يأتون من قرى بعيدة ليومين أو ثلاثة لطحن قمحهم. (مصدر: \"الطواحين المائية في فلسطين\" – د. شريف كناعنة).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"العيون في فلسطين\" – أريج"]'::jsonb,'["روماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a86fc049d470','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','أقدم مدينة في التاريخ، تعود للعصر الحجري الحديث (9000 ق.م).','[{"title":"الموقع والاكتشاف","draft_text":"يقع تل السلطان على بعد كيلومترين شمال وسط أريحا، قرب عين السلطان. هو تل أثري بيضاوي الشكل، يعود أقدم طبقاته إلى العصر الحجري الحديث ما قبل الفخار (حوالي 9000 ق.م)، مما يجعله أقدم مدينة مأهولة باستمرار في تاريخ البشرية. اكتشفته بعثة كاثلين كينيون البريطانية في الخمسينيات، وأظهرت الحفريات 23 طبقة أثرية متعاقبة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"أريحا الكنعانية: البرج والأسوار","draft_text":"أروع ما في تل السلطان هو البرج الدائري الضخم (ارتفاعه 8.5 متر) والسور الحجري الذي يعود للألف التاسع قبل الميلاد. هذا البرج هو أقدم بناء حجري بهذا الحجم في العالم. بناه سكان أريحا الأوائل، وهم مجتمع زراعي متقدم سبق الأسر المصرية بآلاف السنين. الرواية الفلسطينية تفخر بأن أجدادها هم بناة أول مدينة في التاريخ. (مصدر: \"أريحا: أقدم مدينة في العالم\" – كاثلين كينيون، تقارير دائرة الآثار الفلسطينية، اليونسكو).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الرواية المضادة: قصة يوشع","draft_text":"التوراة تروي أن يشوع بن نون دمر أسوار أريحا ونفخ في الأبواق. الرواية الفلسطينية تصحح: طبقات تل السلطان الأثرية لا تظهر أي دمار مفاجئ في العصر البرونزي المتأخر (زمن يشوع المفترض). المدينة كانت مهجورة في ذلك الوقت أصلاً، أو دمرت قبل ذلك بقرون. قصة يشوع هي أسطورة توراتية لا يدعمها علم الآثار. أريحا الكنعانية استمرت كمدينة فلسطينية متصلة الحضارة، لا كمدينة دمرها غزاة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصور اللاحقة","draft_text":"بعد العصر البرونزي، استمر السكن في أريحا خلال العصر الحديدي والفارسي والروماني (حيث بنى هيرودس قصراً شتوياً ومدينة). في العصر الإسلامي، تحولت أريحا إلى مدينة زراعية تشتهر بالنخيل والموز. اليوم، تل السلطان موقع تراث عالمي مقترح، لكنه يعاني من الإهمال والتعديات.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"أريحا: أقدم مدينة\" – كاثلين كينيون، اليونسكو"]'::jsonb,'["عصر حجري","برونزي","كنعاني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-cc4465115964','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','دير أرثوذكسي على الجبل حيث صام المسيح.','[{"title":"الموقع والجغرافيا المقدسة","draft_text":"يقع دير قرنطل على قمة جبل الأربعين (جبل التجربة)، غرب أريحا. الجبل شديد الانحدار، يطل على وادي الأردن والبحر الميت. بحسب الأناجيل، هذا هو الجبل الذي صام فيه المسيح أربعين يوماً وجربه الشيطان. الاسم \"قرنطل\" مشتق من \"كرنتينا\" اللاتينية (الأربعين).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الدير اليوناني الأرثوذكسي","draft_text":"بُني الدير الحالي في القرن 19 على أنقاض دير بيزنطي أقدم. لكن المغارة التي صام فيها المسيح موجودة في قلب الجبل منذ الأزل. الدير مبني على مصاطب صخرية، وكأنه متشبث بالجبل. الوصول إليه كان يتم بحبل حتى منتصف القرن 20. اليوم، تلفريك سياحي يصعد الزوار إلى قمة الجبل.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النساك والمتوحدون","draft_text":"منذ القرن الرابع، سكن النساك المسيحيون كهوف هذا الجبل. عاشوا حياة تقشف مطلق، يأكلون الأعشاب ويصلون طوال النهار. دير قرنطل هو أحد آخر الأدلة على تقليد \"الصحراء المقدسة\" في فلسطين، حيث كان النساك يتحدون الجسد والطبيعة للوصول إلى الله. الرواية الفلسطينية المحلية تحترم هذا الإرث النسكي، وتعتبره جزءاً من تراث وادي الأردن. (مصدر: \"دليل الأديرة الفلسطينية\" – مطرانية الروم الأرثوذكس).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"الأديرة في فلسطين\" – الأب عيسى مصلح"]'::jsonb,'["بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-b5f00132ee24','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','نبع ماء تاريخي مرتبط بتل السلطان.','[]'::jsonb,'["\"مصادر المياه\" – أريج"]'::jsonb,'["كنعاني","روماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-ce23c41d7641','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام ضخم يخدم كمركز لموسم سنوي.','[]'::jsonb,'["\"الموسم النبوي\" – كناعنة"]'::jsonb,'["أيوبي","مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-0285c869e647','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','قصر أثري مع فسيفساء وبركة ماء، بناه الخليفة هشام. قصر صحراوي بفسيفساء "شجرة الحياة"، بناه هشام بن عبد الملك.','[{"title":"المجمع الأموي ووظائفه","draft_text":"يقع قصر هشام على بعد نحو خمسة كيلومترات شمال مدينة أريحا. تعرض المسودة القصر بوصفه مجمعاً أموياً يضم قصراً وجامعاً وحمامات وساحة، وتشير إلى فسيفساء شجرة الحياة والزخارف الجصية، مع بقاء تحديد الباني والتاريخ الدقيق ووظائف المجمع خاضعة لمراجعة تقارير الحفريات والمراجع الأصلية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"بوابات التدقيق","draft_text":"تحتاج المسودة إلى مطابقة اسم الباني، تاريخ الإنشاء، نتائج الحفريات، وصف الفسيفساء، وحالة الحفظ الحالية بمصادر مؤسسية وأثرية محددة الصفحات.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"الفن الأموي\" – د. محمد أبو الفتوح","\"القصور الأموية\" – د. محمد أبو الفتوح"]'::jsonb,'["أموي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-7551f628d089','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','قناة مائية رومانية معلقة.','[{"title":"الموقع والبناء","draft_text":"وادي القلط هو وادٍ صخري عميق يصل بين القدس وأريحا. على جدرانه الشمالية، بنى الرومان قناة مائية معلقة (أكوا دكت) تنقل مياه عين فاره وعين القلط إلى أريحا وقصر هشام. القناة محفورة في الصخر ومبنية على قناطر في الأجزاء المنحدرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العبقرية الهندسية","draft_text":"ما يجعل القناة معجزة هو انحدارها المدروس بدقة (0.5%)، مما يسمح للماء بالجريان بقوة دون أن يتوقف أو يفيض. بُنيت في القرن الأول أو الثاني الميلادي، وجُددت في العصر الأموي. لا تزال أجزاء منها تستخدم حتى اليوم لري بساتين أريحا. هذه الاستمرارية هي دليل حي على عبقرية الهندسة الرومانية والأموية. (مصدر: \"أنظمة المياه\" – م. ناصر الدين).\n\nقطاع غزة","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"أنظمة الري\" – جامعة بيرزيت"]'::jsonb,'["روماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-c4d8c9fdd1f0','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام كبير بناه صلاح الدين وأكمله بيبرس، يحتفل الفلسطينيون بموسمه السنوي.','[]'::jsonb,'["\"الموسم النبوي في فلسطين\" – د. شريف كناعنة"]'::jsonb,'["أيوبي","مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-2e45744cdab4','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','بناه الظاهر بيبرس على أنقاض معبد روماني وكنيسة بيزنطية.','[{"title":"طبقات المكان","draft_text":"يقع المسجد العمري الكبير في البلدة القديمة لمدينة غزة. تربط المسودة الموقع بتعاقب استخدامات دينية ومعمارية قديمة وبيزنطية وإسلامية، وتشير إلى توسعات مملوكية وعثمانية وإلى أضرار حديثة. كل تفصيل زمني ومعماري يحتاج إحالة دقيقة وتحديثاً ميدانياً وحقوقياً قبل الاعتماد.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"بوابات التدقيق","draft_text":"تحتاج المادة إلى مصادر أثرية ومعمارية وسجلات محلية وتقييم محدث للأضرار، مع فصل الدليل التاريخي عن الرواية التحريرية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"آثار غزة\" – بلدية غزة، وزارة السياحة"]'::jsonb,'["روماني","بيزنطي","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-21150eefdea6','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','موقع أثري هام، كان مرفأً تجارياً.','[{"title":"الموقع","draft_text":"يقع تل العجول جنوب مدينة غزة، قرب وادي غزة. هو تل أثري ضخم كان في الأصل ميناء غزة القديم ومستوطنة تجارية رئيسية في العصر البرونزي (2000-1200 ق.م).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الاكتشافات","draft_text":"حفريات فلندرز بيتري (1930s) كشفت عن مدينة غنية جداً، بذهبها ومجوهراتها (كنز تل العجول) وعلاقاتها التجارية مع مصر وقبرص وكريت. كانت المدينة مركزاً لتصدير النبيذ والزيت الفلسطيني. الرواية الفلسطينية ترى في هذا الكنز دليلاً على ثراء غزة القديمة ودورها التجاري العالمي. (مصدر: \"حفريات تل العجول\" – المتحف البريطاني).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الفلسطينيون القدماء","draft_text":"في الطبقات العليا من التل، عُثر على فخار فلسطيني (فلسطيّ) مميز، مما يؤكد أن الفلسطينيين القدماء سكنوا غزة وجعلوها إحدى مدنهم الرئيسية. هذه الاستمرارية في الاسم (فلسطيني) من العصر الحديدي حتى اليوم هي جوهر الرواية الفلسطينية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"حفريات غزة\" – المدرسة البريطانية للآثار"]'::jsonb,'["برونزي","كنعاني","فلسطيني قديم"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-3ded44be126d','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','حمام أثري لا يزال قائماً.','[]'::jsonb,'["Riwaq"]'::jsonb,'["مملوكي","عثماني"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-5e98cf44d976','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','قلعة بناها السلطان برقوق، دُمرت أجزاء منها.','[]'::jsonb,'["\"قلاع فلسطين\" – د. النتشة"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-e1e3de7b8519','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','من أقدم كنائس غزة (القرن 5م)، دُفن فيها القديس برفيريوس.','[{"title":"التأسيس","draft_text":"تقع كنيسة القديس برفيريوس في حي الزيتون بغزة. بُنيت عام 425م فوق معبد وثني، بأمر من القديس برفيريوس أسقف غزة. هي ثالث أقدم كنيسة في فلسطين ما زالت تستخدم للصلاة. برفيريوس هو قديس فلسطيني محلي، وُلد في تسالونيكي لكنه عاش ومات في غزة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العمارة والتاريخ","draft_text":"الكنيسة بازيليكا ضخمة بأعمدة رخامية وأرضيات فسيفسائية. صمدت أمام الزلازل والحروب والغزوات. في العصر الإسلامي، تحولت إلى مسجد لفترة وجيزة، ثم أُعيدت للروم الأرثوذكس. جُددت في العصر الصليبي والعثماني.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"قصف 2023","draft_text":"في أكتوبر 2023، تعرضت الكنيسة لقصف إسرائيلي أثناء الحرب على غزة، مما أدى لاستشهاد 18 مسيحياً كانوا يحتمون بها. هذا الحدث ليس مجرد خبر، بل هو فصل دامٍ في الرواية الفلسطينية الحية. الكنيسة التي صمدت 1600 عام تتعرض اليوم للقصف. (مصدر: بطريركية الروم الأرثوذكس في القدس، تقارير وكالة وفا).","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"تاريخ كنيسة غزة\" – الأرثوذكس"]'::jsonb,'["بيزنطي","صليبي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-015f495c4236','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','تعرض المسودة مدينة غزة القديمة كطبقات متصلة من الميناء والتجارة والعمارة الدينية والمدنية، مع إبراز آثار الحروب الحديثة وحاجة التوثيق إلى تحديث مستمر.','[{"title":"الموقع والتاريخ","draft_text":"غزة هي إحدى أقدم المدن المأهولة في العالم (أكثر من 5000 عام). تقع على الطريق الساحلي بين مصر وكنعان، مما جعلها بوابة فلسطين الجنوبية ومفتاحها الاستراتيجي. اسمها كنعاني قديم، ورد في رسائل تل العمارنة وفي التوراة وفي النصوص الآشورية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الكنعانيون والفلسطينيون القدماء","draft_text":"سكن الكنعانيون غزة منذ الألف الثالث قبل الميلاد. في القرن 12 ق.م، استقر فيها \"شعوب البحر\" (الفلسطيون القدامى) الذين أعطوا فلسطين اسمها. كانت غزة إحدى مدن البنتابوليس الفلسطينية الخمس (مع عسقلان وأشدود وعقرون وجت). تماثيل الآلهة الفلسطينية (داجون) عُثر عليها في تل العجول. الرواية الفلسطينية ترى في هؤلاء الفلسطيين أجداداً روحيين، وتؤكد أن اسم \"فلسطين\" وُلد في غزة قبل 3000 عام.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الرومان والبيزنطيون والعرب","draft_text":"ازدهرت غزة في العصر الروماني كمركز تجاري وثقافي. كانت تمتلك مدرسة بلاغة شهيرة. في العصر البيزنطي، أصبحت أسقفية مهمة، وشُيدت فيها كنائس ضخمة (كنيسة القديس برفيريوس). فتحها عمرو بن العاص في القرن السابع، واستمرت كمدينة إسلامية عربية.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"غزة الإسلامية والعثمانية","draft_text":"في العصر المملوكي، كانت غزة عاصمة نيابة (ولاية) تمتد من رفح إلى قيسارية. بنى المماليك فيها المسجد العمري الكبير، وقلعة برقوق، وخان يونس. في العصر العثماني، أصبحت غزة قاعدة للحجاج المصريين. اشتهرت بتجارة الحبوب والقطن والصابون.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النكبة والقطاع المحاصر","draft_text":"بعد نكبة 1948، استقبل قطاع غزة مئات آلاف اللاجئين، وتضاعف سكانه. احتلته مصر ثم إسرائيل (1967)، ثم انسحبت إسرائيل أحادياً (2005) لكنها فرضت حصاراً برياً وبحرياً وجوياً خانقاً منذ 2007. الحروب المتكررة (2008، 2012، 2014، 2023-2024) دمرت أجزاء كبيرة من تراث غزة. الرواية الفلسطينية اليوم هي رواية صمود أسطوري؛ شعب يعيش تحت الحصار والحرب، ويعيد بناء مدينته وتراثه من الركام كل مرة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"غزة عبر التاريخ\" – د. عاطف أبو سيف، سجلات المحكمة الشرعية في غزة"]'::jsonb,'["كنعاني","روماني","بيزنطي","إسلامي","مملوكي","عثماني","حديث"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-a77381cd3cae','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','مقام تاريخي في حي الرمال.','[]'::jsonb,'["\"المقامات في غزة\" – وزارة الأوقاف"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-99f520b3d607','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'catalogSummary','الميناء التاريخي للمدينة.','[]'::jsonb,'["\"غزة عبر التاريخ\" – د. عاطف أبو سيف"]'::jsonb,'["روماني","بيزنطي","إسلامي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-0a78d22c1a69','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','خان أثري بناه الأمير يونس النورزي في القرن 14.','[{"title":"التأسيس","draft_text":"خان يونس مدينة في جنوب قطاع غزة. تأسست في العصر المملوكي (القرن 14) على يد الأمير يونس النورزي الداودار، الذي بنى فيها خاناً تجارياً ضخماً للحجاج والتجار. الخان كان محطة رئيسية على طريق الحج المصري إلى مكة.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"الخان والمدينة","draft_text":"الخان كان بناءً مربعاً بفناء وسطي وإسطبلات وغرف. حوله نمت مدينة زراعية. بعد تراجع طريق الحج، تحولت خان يونس إلى بلدة زراعية. بعد 1948، أقيم فيها مخيم كبير للاجئين. اليوم، هي ثاني أكبر مدن قطاع غزة، وتعرضت لتدمير هائل في حرب 2023-2024. الرواية الفلسطينية لخان يونس هي رواية التحول من مدينة تجارية مملوكية إلى مخيم لاجئين، ثم إلى مدينة منكوبة تعيد بناء نفسها.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["\"خانات غزة\" – أريج"]'::jsonb,'["مملوكي"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
insert into pal_eyes.original_draft_layers (site_id,source_filename,source_sha256,source_line_count,content_profile,summary_draft,narrative_sections,source_mentions,timeline_periods,verification_status,development_visibility,public_release_status) values ('site-ee0e5bf1f753','نص واحد ملصق .txt','1f82a6c9941063436b40d13e258f7d03b1b3b00ef209494fe7032ee756673f6d',5334,'expandedNarrative','تقدم المسودة رفح بوصفها بوابة فلسطين الجنوبية ومحطة قديمة على الطريق الساحلي، ثم مدينة قسمت الحدود الحديثة نسيجها الاجتماعي والجغرافي.','[{"title":"الموقع والتاريخ","draft_text":"رفح هي أقصى مدينة في جنوب قطاع غزة، على الحدود مع مصر. اسمها كنعاني قديم (رفيحو). كانت محطة على الطريق الساحلي بين مصر وكنعان. في العصر الروماني، كانت مدينة حدودية بين ولاية فلسطين وولاية مصر.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"العصر الإسلامي","draft_text":"فتحها عمرو بن العاص، وأصبحت محطة للحج والتجارة. في العصر العثماني، كانت رفح قرية حدودية صغيرة بين ولاية مصر وولاية الشام.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."},{"title":"النكبة والحدود المصطنعة","draft_text":"بعد نكبة 1948، قُسمت رفح إلى شطرين: رفح الفلسطينية (في قطاع غزة) ورفح المصرية. هذا التقسيم مزق العائلات. بعد 1967، دمرت إسرائيل أجزاء واسعة من رفح لشق طريق عسكري. واليوم، رفح هي نقطة العبور الوحيدة لسكان غزة إلى العالم الخارجي، وتتعرض لاجتياحات وحروب متكررة. الرواية الفلسطينية لرفح هي رواية الحدود المأساوية، والأنفاق، والصمود على خط النار.","evidence_note":"مسودة أصلية تحتاج تحققاً مستقلاً."}]'::jsonb,'["إحالات الرواية الموسعة في الوثيقة المرجعية — تحتاج تحققاً ببليوغرافياً"]'::jsonb,'["كنعاني","روماني","إسلامي","عثماني","حديث"]'::jsonb,'ORIGINAL_DRAFT_UNDER_REVIEW','DEBUG_ONLY','BLOCKED') on conflict (site_id) do update set summary_draft=excluded.summary_draft,narrative_sections=excluded.narrative_sections,source_mentions=excluded.source_mentions,timeline_periods=excluded.timeline_periods,verification_status=excluded.verification_status,public_release_status=BLOCKED;
